package api

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
)

// TrailsEnabled probes trail availability: 2xx=true, 403/404/410=false,
// everything else ambiguous.
func (c *Client) TrailsEnabled(ctx context.Context, forge, owner, repo string) (bool, error) {
	resp, err := c.Get(ctx, fmt.Sprintf("/api/v1/trails/%s/%s/%s?limit=1",
		url.PathEscape(forge), url.PathEscape(owner), url.PathEscape(repo)))
	if err != nil {
		return false, fmt.Errorf("probe trails enablement: %w", err)
	}
	defer resp.Body.Close()
	// Drain (bounded) so net/http can reuse the connection; the body is unused.
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<16)) //nolint:errcheck // best-effort drain
	if resp.StatusCode >= http.StatusOK && resp.StatusCode < http.StatusMultipleChoices {
		return true, nil
	}
	switch resp.StatusCode {
	case http.StatusForbidden, http.StatusNotFound, http.StatusGone:
		return false, nil
	default:
		return false, fmt.Errorf("probe trails enablement: unexpected status %s", resp.Status)
	}
}

package api

import (
	"time"

	"github.com/entireio/cli/cmd/entire/cli/trail"
)

// TrailListResponse is the response from GET /api/v1/trails/:org/:repo.
// The endpoint paginates: Trails holds one page (server max 200 rows) and
// Total is the full match count for the requested filters.
type TrailListResponse struct {
	Trails        []TrailResource `json:"trails"`
	Total         int             `json:"total"`
	Limit         int             `json:"limit"`
	Offset        int             `json:"offset"`
	RepoFullName  string          `json:"repo_full_name"`
	DefaultBranch string          `json:"default_branch"`
	UpdatedAt     time.Time       `json:"updated_at"`
}

// TrailResource represents a single trail from the API.
type TrailResource struct {
	ID        string           `json:"id,omitempty"`
	Number    int              `json:"number,omitempty"`
	URL       string           `json:"url,omitempty"`
	Branch    string           `json:"branch"`
	Base      string           `json:"base"`
	Title     string           `json:"title"`
	Body      string           `json:"body"`
	Status    string           `json:"status"`
	Phase     string           `json:"phase,omitempty"`
	Author    *trail.Author    `json:"author"`
	Assignees []string         `json:"assignees"`
	Labels    []string         `json:"labels"`
	Priority  string           `json:"priority,omitempty"`
	Type      string           `json:"type,omitempty"`
	Reviewers []trail.Reviewer `json:"reviewers,omitempty"`
	// RequestedReviewers holds the logins requested for review (distinct from
	// Reviewers, which carries per-login review status). The replace-set
	// --add-reviewer/--remove-reviewer merge computes the new set from this.
	RequestedReviewers []string   `json:"requested_reviewers,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
	UpdatedAt          time.Time  `json:"updated_at"`
	MergedAt           *time.Time `json:"merged_at,omitempty"`
	CommentCount       int        `json:"comment_count,omitempty"`
	UnresolvedCount    int        `json:"unresolved_count,omitempty"`
	CheckpointCount    int        `json:"checkpoint_count,omitempty"`
	CommitsAhead       int        `json:"commits_ahead,omitempty"`
	// BodyDocument carries the trail's description (collaborative editor doc).
	// The list endpoint omits it; the detail endpoint populates it.
	BodyDocument *TrailBodyDocument `json:"body_document,omitempty"`
}

// TrailBodyDocument is the trail's description editor document. TextSnapshot is
// the rendered plain text the CLI displays.
type TrailBodyDocument struct {
	TextSnapshot string `json:"text_snapshot"`
}

// ToMetadata converts a TrailResource to a trail.Metadata for display.
func (r *TrailResource) ToMetadata() *trail.Metadata {
	m := &trail.Metadata{
		Number:    r.Number,
		TrailID:   trail.ID(r.ID),
		URL:       r.URL,
		Branch:    r.Branch,
		Base:      r.Base,
		Title:     r.Title,
		Body:      r.Body,
		Status:    trail.Status(r.Status),
		Phase:     r.Phase,
		Author:    r.Author,
		Assignees: r.Assignees,
		Labels:    r.Labels,
		Type:      trail.Type(r.Type),
		Priority:  trail.Priority(r.Priority),
		Reviewers: r.Reviewers,
		CreatedAt: r.CreatedAt,
		UpdatedAt: r.UpdatedAt,
		MergedAt:  r.MergedAt,
	}
	if m.Assignees == nil {
		m.Assignees = []string{}
	}
	if m.Labels == nil {
		m.Labels = []string{}
	}
	return m
}

// TrailCreateRequest is the body for POST /api/v1/trails/:host/:owner/:repo.
type TrailCreateRequest struct {
	Title      string `json:"title"`
	Body       string `json:"body,omitempty"`
	BranchName string `json:"branch_name,omitempty"`
	// BranchAction is "create" (default) or "link". The CLI sends "link" to
	// attach an already-pushed branch instead of backfilling it at base. Omit
	// both branch_name and branch_action to create a branchless trail.
	BranchAction string   `json:"branch_action,omitempty"`
	Base         string   `json:"base,omitempty"`
	Status       string   `json:"status,omitempty"`
	Assignees    []string `json:"assignees,omitempty"`
	Labels       []string `json:"labels,omitempty"`
	Priority     string   `json:"priority,omitempty"`
	Type         string   `json:"type,omitempty"`
}

// TrailCreateResponse is the response from POST /api/v1/trails/:org/:repo.
type TrailCreateResponse struct {
	Trail TrailResource `json:"trail"`
}

// TrailUpdateRequest is the body for PATCH /api/v1/trails/:host/:owner/:repo/:trailId.
// Pointer fields distinguish "not provided" (nil) from "set to value".
// For slices, *[]string is used so nil means "no change" while &[]string{} means "clear".
type TrailUpdateRequest struct {
	Status             *string   `json:"status,omitempty"`
	Title              *string   `json:"title,omitempty"`
	Body               *string   `json:"body,omitempty"`
	Labels             *[]string `json:"labels,omitempty"`
	Assignees          *[]string `json:"assignees,omitempty"`
	RequestedReviewers *[]string `json:"requested_reviewers,omitempty"`
	Type               *string   `json:"type,omitempty"`
	Priority           *string   `json:"priority,omitempty"`
}

// TrailUpdateResponse is the response from PATCH /api/v1/trails/:org/:repo/:trailId.
type TrailUpdateResponse struct {
	Trail TrailResource `json:"trail"`
}

// TrailDeleteResponse is the response from DELETE /api/v1/trails/:host/:owner/:repo/:number.
// OK is the server's explicit success signal; a destructive delete should not be
// reported as done unless it is true.
type TrailDeleteResponse struct {
	OK bool `json:"ok"`
}

// TrailApproval is a single approval decision on a trail.
type TrailApproval struct {
	ID        string        `json:"id"`
	Author    *trail.Author `json:"author"`
	Event     string        `json:"event"` // "approved" | "changes_requested"
	Body      string        `json:"body,omitempty"`
	CommitSHA string        `json:"commit_sha,omitempty"`
	CreatedAt time.Time     `json:"created_at"`
}

// TrailApprovalRequest is the body for POST .../:number/approvals.
// Event is "APPROVE" or "REQUEST_CHANGES"; Body is required for REQUEST_CHANGES.
type TrailApprovalRequest struct {
	Event string `json:"event"`
	Body  string `json:"body,omitempty"`
}

// TrailApprovalResponse is the response from POST .../:number/approvals.
type TrailApprovalResponse struct {
	OK       bool          `json:"ok"`
	Approval TrailApproval `json:"approval"`
}

// TrailApprovalsResponse is the response from GET .../:number/approvals.
type TrailApprovalsResponse struct {
	Approvals []TrailApproval `json:"approvals"`
}

package cli

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

// NewAuthenticatedAPIClient creates an API client targeting api.BaseURL()
// (the data API origin) carrying a token valid for that audience, minted by
// exchanging the matching login context's JWT at its own core (see
// auth.ResolveDataAPIToken).
//
// Pass insecureHTTP=true to allow plain HTTP base URLs for local
// development. Only the data origin is checked here — the bearer travels
// there on resource requests; the exchange leg is guarded by the
// per-context token manager (https required outside loopback/opt-in).
func NewAuthenticatedAPIClient(ctx context.Context, insecureHTTP bool) (*api.Client, error) {
	dataURL := api.BaseURL()
	if insecureHTTP {
		auth.EnableInsecureHTTP()
	} else if err := api.RequireSecureURL(dataURL); err != nil {
		return nil, fmt.Errorf("base URL check: %w", err)
	}

	// ResolveDataAPIToken discovers which login context the data host trusts
	// (via its /.well-known/entire-api.json) and exchanges that context's
	// token for the advertised audience. It normalises dataURL to an origin
	// internally.
	token, err := auth.ResolveDataAPIToken(ctx, dataURL)
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			// Wrap the original err (not the sentinel) so any context
			// the tokenmanager attached — keyring backend message,
			// expired-token reason — survives to the caller. The
			// errors.Is(err, auth.ErrNotLoggedIn) chain is preserved
			// because err already wraps the sentinel; replacing it
			// with the bare sentinel would drop that context for
			// zero behavioural gain.
			return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
		}
		return nil, fmt.Errorf("resolve API token: %w", err)
	}

	return api.NewClient(token), nil
}

// NewAuthenticatedEntireAPICellClient creates an API client for repo-scoped
// entire-api routes (e.g. experts). It exchanges the login JWT for a
// jurisdictional identity token and dials the entire-api cell directly, because
// the BFF does not proxy these routes for bearer callers (COR-666).
//
// fullName (owner/repo) and/or ulid identify the repo whose cell to reach. When
// either is supplied, the repo's OWNING cell + jurisdiction are resolved from
// the control plane (mirroring the BFF's per-repo cell selection) so the call
// lands in the region that hosts the repo. Resolution is best-effort: any
// failure yields a nil target and NewEntireAPICellClient falls back to
// home-jurisdiction routing, so the common same-region case never regresses.
func NewAuthenticatedEntireAPICellClient(ctx context.Context, insecureHTTP bool, fullName, ulid string) (*api.Client, error) {
	target := resolveRepoCellTarget(ctx, fullName, ulid)
	// NewEntireAPICellClient already returns user-facing, context-rich errors
	// (login hint, discovery-unavailable, region guidance); re-wrapping here
	// would bury them, so surface them verbatim.
	return auth.NewEntireAPICellClient(ctx, insecureHTTP, target) //nolint:wrapcheck // pass through contextual auth errors
}

package httpapi

import (
	"context"
	"log/slog"
	"net/http"
	"time"

	"github.com/danielgtaylor/huma/v2"
	"github.com/danielgtaylor/huma/v2/adapters/humachi"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/nats-io/nats.go"

	"github.com/entirehq/entiredb/modules/analytics"
	"github.com/entirehq/entiredb/modules/ratelimit"

	"github.com/entirehq/entire-api/internal/auth"
	"github.com/entirehq/entire-api/internal/authz"
	"github.com/entirehq/entire-api/internal/checkpointpublish"
	"github.com/entirehq/entire-api/internal/checkpointredact"
	"github.com/entirehq/entire-api/internal/commitmsg"
	"github.com/entirehq/entire-api/internal/config"
	"github.com/entirehq/entire-api/internal/coreapi"
	"github.com/entirehq/entire-api/internal/repoapi"
	"github.com/entirehq/entire-api/internal/runner"
	"github.com/entirehq/entire-api/internal/runnerissuer"
	"github.com/entirehq/entire-api/internal/snapshot"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entirehq/entire-api/internal/trailblobs"
	"github.com/entirehq/entire-api/internal/trailforge"
	"github.com/entirehq/entire-api/internal/transcript"
	"github.com/entirehq/entire-api/internal/yjsengine"
)

// AuthorUsernameResolver resolves Entire account ULIDs to their GitHub identity
// (login + numeric id). It is the shared serve-time account→identity resolver for
// every contributor surface that groups by the account ULID: the checkpoint render
// (commitAuthorUsername / firstCommitAuthorUsername) and the repo-overview
// contributors / contributor-tokens / contributor-agents panels.
type AuthorUsernameResolver interface {
	AccountIdentities(ctx context.Context, accountIDs []string) (map[string]coreapi.GitHubIdentity, error)
}

// AuthorEmailResolver resolves commit author git emails → their linked account +
// GitHub identity (entire-core lookupAuthorAccounts, COR-659). It is the serve-time
// email → GitHub login resolver for commitAuthorUsername on every commit (entire.io
// live-provider resolveAuthorLogins). Unlike AuthorUsernameResolver — keyed by the
// account ULID stamped on checkpoint_commits at ingest, so only checkpoint-anchored
// commits carry it — this keys by the commit's git author email, which every commit
// has, so read-through (non-anchoring) commits resolve too.
type AuthorEmailResolver interface {
	AuthorAccounts(ctx context.Context, emails []string) (map[string]coreapi.AuthorAccounts, error)
}

// RepoCollaboratorsResolver lists one page of accounts with effective access
// to a repo, via entire-core's GET /repos/{repoId}/collaborators (built in
// parallel, entiredb repo). Backs the /repos/{repo_id}/collaborators
// pass-through, which the BFF uses to build an author-filter picker on real
// account IDs instead of raw GitHub logins. pageSize/pageToken forward
// verbatim; the returned nextPageToken is empty on the last page.
type RepoCollaboratorsResolver interface {
	ListRepoCollaborators(ctx context.Context, repoID string, pageSize int, pageToken string) ([]coreapi.RepoCollaborator, string, error)
}

// MirrorResyncer resyncs a mirror placement via entire-core (POST
// /mirrors/{id}/resync); satisfied by *coreapi.Client.
type MirrorResyncer interface {
	ResyncMirror(ctx context.Context, repoID string) error
}

// APIBase is the chi mount point for the whole Huma API. Operations and the
// OpenAPI/docs handlers live under it, so /me is served at /api/v1/me and the
// spec at /api/v1/openapi.yaml. It is also declared as the OpenAPI server URL,
// which keeps the emitted path keys relative to it (bare /me, not /api/v1/me) —
// the convention the api-gateway expects: it derives the proxy base from the
// spec URL's directory and joins the bare key, so a gateway client reaches
// /v1/me.
const APIBase = "/api/v1"

// apiPrefix namespaces the product operations within APIBase. The op
// constructors prepend it, so per-route paths are written relative to it. It is
// empty: the product surface is primary and owns the bare /api/v1/repos/...,
// sessions, checkpoints, and /me. entiredb's raw git plane is sub-pathed under
// /git at the gateway (see internal/gateway/config topology), so the two stay
// disjoint without the product carrying a namespace segment of its own.
const apiPrefix = ""

// baseDeps is what every service's HTTP layer needs, independent of store.
// Reader is the process-shared authz.Reader (regional read-only SpiceDB,
// dialed once at startup) the per-request AccessChecker wraps; nil is fine for
// router/health tests that never reach a gate (tokenless requests short-circuit
// at requireAuth).
type baseDeps struct {
	Config        config.Common
	Authenticator *auth.Authenticator
	Reader        *authz.Reader
	// Approval gates every authenticated route on the caller's live waitlist
	// state (COR-940). nil disables the gate (tests, and local dev without the
	// internal-mTLS Core client that backs the lookup).
	Approval    *auth.ApprovalChecker
	ReadyChecks []ReadyCheck
	// Analytics is the shared PostHog capture client backing the per-request
	// api_request event (backend DAU/MAU). Only the serve process sets it; a nil
	// or disabled client makes the capture middleware a no-op. Best-effort
	// telemetry — never on the request's critical path.
	Analytics *analytics.Client
	// RateLimiter is the per-IP front-door throttle applied as the outermost mux
	// middleware: a generous global per-IP cap plus a stricter tier on the
	// read-through / anonymous-mint endpoints. Defense-in-depth behind the edge,
	// not the primary control. nil disables it — only the serve path sets it, so
	// router/health tests (which fire many requests from one loopback IP) run
	// unthrottled.
	RateLimiter *ratelimit.HTTPLimiter
}

// UserActivityDeps is the user-activity service's HTTP deps (user store).
// Store is the userReader read surface (satisfied by *store.UserStore) so the
// /me read path can be exercised through a fake.
type UserActivityDeps struct {
	baseDeps
	Store userReader
	// ResolveOrigins maps placement repo ids → origin keys (the my_activity row
	// identity) for the ?repo_ids= / ?repo= filters, backed by the repo store's
	// RepoGroupIDs. Ids it can't resolve are missing from the map and filter
	// by their own id (a native repo's origin). nil (tests without a repo
	// store) filters by the ids themselves.
	ResolveOrigins func(ctx context.Context, repoIDs []string) map[string]string
	// ResolveLocalPlacements maps origin keys (repo_group ULIDs) → THIS region's
	// own placement id for each, backed by the repo store's ReposByGroup. The /me
	// access gate uses it to test whether the caller can pull a deduped mirror
	// row's logical repo when the row's last-reporter repo_id is a foreign
	// placement. An origin with no local placement is absent from the map; nil
	// (tests without a repo store) leaves the gate on the repo_id check alone.
	ResolveLocalPlacements func(ctx context.Context, origins []string) map[string]string
}

// CheckpointPayloadRepoClient combines publication's write surface with the
// immutable commit read used to verify a request's checkpoint trailer.
type CheckpointPayloadRepoClient interface {
	checkpointpublish.RepoClient
	BatchCommits(ctx context.Context, base, repoID string, shas []string, parseTrailers bool) (map[string]repoapi.Commit, error)
}

// RunnerLauncher is the manual-trigger write boundary. It intentionally exposes
// only LaunchRun: route code cannot bypass its validation, atomic active-slot
// claim, or provision-work publish contract.
type RunnerLauncher interface {
	LaunchRun(context.Context, runner.RunIntent) (runner.LaunchResult, error)
}

// RepoActivityDeps is the repo-activity service's HTTP deps (repo store).
type RepoActivityDeps struct {
	baseDeps
	Store *store.RepoStore
	// RepoAPIBase is the entiredb repo-API entry used by content read-through
	// (transcripts) — the cell's clustered entiredb upstream. Empty disables
	// those endpoints (500 not-configured). Per-repo node/cluster routing is the
	// ContentTransport's job (replica redirects), not a per-repo base.
	RepoAPIBase string
	// ContentTransport wraps a per-request bearer-forwarding transport with the
	// cell's entiredb replica-redirect routing (shared node cache), so a content
	// read-through reaches the repo's hosting node regardless of which entry it
	// starts from. nil → the bearer transport is used directly (single-host dev/test).
	ContentTransport func(inner http.RoundTripper) http.RoundTripper
	// ContentBaseTransport is the base RoundTripper the bearer-forwarding content
	// client dials over. In production it is the workload-mTLS transport to the
	// internal entiredb svctok listener (presents activity's client cert; the
	// forwarded caller bearer still drives entiredb's per-user authz). nil → a
	// shared plain instrumented transport (dev/test, or the public fallback base).
	ContentBaseTransport http.RoundTripper
	// AuthorUsernames resolves account ULIDs → GitHub login for render
	// (firstCommitAuthorUsername, contributor panels), via entire-core's
	// internal-mTLS COR-516 read. nil when internal mTLS isn't configured
	// (local dev) — render then falls back to the stored login only.
	AuthorUsernames AuthorUsernameResolver
	// AuthorEmails resolves commit author git emails → GitHub login for
	// commitAuthorUsername on every commit (anchoring or not), via entire-core's
	// internal-mTLS COR-659 read. nil when internal mTLS isn't configured (local
	// dev) — commitAuthorUsername then resolves to null.
	AuthorEmails AuthorEmailResolver
	// RepoCollaborators resolves a repo's effective-access account list for
	// GET /repos/{repo_id}/collaborators, via entire-core's internal-mTLS
	// collaborators read. nil when internal mTLS isn't configured (local dev)
	// — the route then 500s (not configured).
	RepoCollaborators RepoCollaboratorsResolver
	// Snapshot captures + serves the encrypted transcript snapshot that backs
	// anonymous shared-session reads (the share endpoints write it; the
	// optional-auth transcript read serves it for a viewer with no repo access).
	// nil disables sharing — the share endpoints 500 and the read path serves only
	// the live (member) branch — but the server wiring always supplies one (a local
	// cipher + filesystem store in dev), so it is non-nil in practice.
	Snapshot *snapshot.Capturer
	// CheckpointPayloadRepos is the cert-only entiredb client behind
	// provider-transcript-v1 ingestion. It is nil unless workload mTLS is
	// configured; the endpoint then returns a fail-closed 503. Entiredb owns
	// mirror credential minting so no GitHub write token enters this process.
	CheckpointPayloadRepos CheckpointPayloadRepoClient
	// CheckpointPayloadPolicy is normally derived from CheckpointPayloadRepos.
	// Keeping the narrow resolver injectable makes route contract tests exercise
	// publication without constructing an entire Repo API policy fixture.
	CheckpointPayloadPolicy interface {
		Resolve(ctx context.Context, repoID, defaultBranch, reviewedSHA string) ([]checkpointredact.CustomRule, error)
	}
	// MirrorResync resyncs the checkpoint storage repo after a ref-backed
	// checkpoint payload publishes (see maybeResyncCheckpointStorage). nil —
	// tests, and local dev without the internal-mTLS Core client — skips the
	// trigger; publication is unaffected.
	MirrorResync MirrorResyncer
	// Attachments is the per-cell S3-compatible object store backing the trail
	// attachment "blob quartet" (upload intent / complete / serve / delete).
	// Opt-in: nil means the store was never configured (all ENTIRE_TRAIL_BLOB_*
	// vars unset — zero-env boot), and every attachment route degrades to 503
	// attachments_not_configured rather than touching a client that doesn't
	// exist. Populated in internal/server/api.go from trailblobs.New, which
	// itself fails closed (a non-nil error, not a nil Store) on a PARTIALLY
	// configured set of vars — so a nil here in production always means
	// "deliberately disabled", never "misconfigured".
	Attachments trailblobs.Store
	// commitCache memoises entiredb commit-list pages, keyed by repo + branch tip +
	// page token (so a ref move invalidates naturally). nil is a valid no-op cache.
	commitCache *ttlCache[*repoapi.ListCommitsResponse]
	// branchSHAsCache memoises a branch's reachable commit-SHA set (for the ?branch=
	// filter), keyed by repo + branch tip. nil is a valid no-op cache.
	branchSHAsCache *ttlCache[[]string]
	// contributorsCache memoises the branch-delta contributor set, keyed by repo +
	// the resolved base+head tip SHAs (from /compare/status). The tip pair pins the
	// delta's history, so the entry is immutable: a push moves a tip → new key → the
	// old entry falls out by TTL. Concurrent cold misses for a key collapse onto one
	// delta walk (GetOrCompute). nil is a valid no-op cache.
	contributorsCache *ttlCache[[]CompareContributor]
	// commitMsgs serves commit message text by SHA, read through entiredb's batch
	// commit endpoint (the message is no longer denormalised on checkpoint_commits).
	// Immutable per (repo, sha), so its cache is never stale.
	commitMsgs *commitmsg.Reader
	// AnonSigner mints short-lived scoped JWTs for anonymous public-repo reads.
	// nil when the signing key is not configured (ENTIRE_ANON_SIGNING_KEY unset),
	// which disables anonymous access entirely.
	AnonSigner *auth.AnonSigner
	// AnonClusterAudience is the cluster's base URL used as the audience origin
	// in minted anonymous JWTs (e.g. "https://royalcanin.partial.to"). Derived
	// from RepoAPIBase (or the internal URL) at startup.
	AnonClusterAudience string
	// RunnerIssuerPublisher publishes this cell's OIDC discovery document and JWKS.
	// nil leaves both public routes unregistered.
	RunnerIssuerPublisher *runnerissuer.Publisher
	// RunnerLauncher is nil while RUNNER_LAUNCH_ENABLED is disabled. The future
	// manual launch route treats nil as unavailable before reading config or store.
	RunnerLauncher RunnerLauncher
	// RunnerIssuerRoutePrefix is the issuer path after removing the public
	// gateway base path, ready for registration in the merged API surface.
	RunnerIssuerRoutePrefix string
	// ForeignRepoNames is the /me last-resort repo-name resolver: it names rows for a
	// repo with no placement in this cell (which have no local metadata and otherwise
	// render as a bare ULID) via a read-time Core batch call, forwarding the caller's
	// bearer, shown-not-stored. The serve process always wires it; nil (tests that
	// wire no Core client) leaves the /me read path byte-for-byte unchanged.
	ForeignRepoNames ForeignRepoNameResolver
	// TranscriptBudget bounds the total blob bytes being parsed concurrently across
	// the process, keyed on in-flight blob size. It covers both the checkpoint-
	// transcript fan-out and the session-transcript merge, which share the parse
	// cost — a per-request concurrency cap alone leaves concurrent requests to
	// multiply. Exhaustion sheds as a 429 after a bounded wait rather than
	// allocating. nil (tests, and any deployment that leaves the budget unset)
	// disables admission — parsing is then unbounded, as before.
	TranscriptBudget *transcript.Budget
	// MetaEngine serves the git-meta routes (GET/POST /repos/{id}/meta?namespace=):
	// live read-throughs and CAS writes of git-meta metadata under refs/meta/. nil
	// disables those routes (500 not-configured) — the serve process wires it via
	// EnableGitMeta; route tests inject a fake. It owns its own read cache.
	MetaEngine MetaEngine
	// Forge is the trails write surface's forge-bound side-effect seam
	// (internal/trailforge.ForgeSync — create/update/delete branch, change
	// proposal, and compare operations). NewRepoActivityDeps defaults this to
	// trailforge.NewNoop() (RFD-023 PR 2: no GitHub-backed implementation
	// wired yet — PR 6 slots one in here without touching the trails write
	// handlers). A caller that builds RepoActivityDeps directly (bypassing
	// NewRepoActivityDeps, e.g. the recap-facet-parity CLI) leaves this nil;
	// registerTrailsWrites falls back to Noop itself so a nil Forge never
	// panics a route that happens to get registered against such deps.
	Forge trailforge.ForgeSync
	// TrailsIngestEnabled gates the cell's service-authenticated write plane ahead
	// of authentication — both the runner-family ingestion endpoints (RFD-023 PR 8,
	// requireIngestEnabled) and the trail command surface (BFF write-repoint,
	// requireCommandEnabled). Defaults false; the serve wiring sets it from
	// config.ActivityAPIConfig.TrailsIngestEnabled. With it off both are inert
	// (503) regardless of the caller. One flag for both — they flip together at
	// cutover.
	// The run upsert + checkpoint-payload pair is exempt (registerRunnerIngest):
	// checkpoint preservation's rollout switch lives in the BFF, and admission
	// here is authn/authz alone.
	TrailsIngestEnabled bool
	// PlatformResourceID is the SpiceDB platform singleton id the service-gated
	// trails write gates check against — write_run_records for ingestion
	// (requireRunRecordWrite) and write_trail_lifecycle for the command surface
	// (requireTrailLifecycleWrite). Set by the serve wiring from
	// config.ActivityAPIConfig.PlatformResourceID; empty in tests that don't
	// exercise those gates.
	PlatformResourceID string
	// GateResultsWritable is the write-flip seam (RFD-023 PR 5, D2) gating
	// whether the approvals-submit synchronous re-eval (trails_approvals.go)
	// persists its fresh `approvals` gate result via InsertGateResult, or only
	// assembles it in-memory for the response. Defaults false (Go zero value):
	// during the mirror phase, this cell only ASSEMBLES gate evaluations — it
	// never becomes the system of record for repo_trail_gate_results until a
	// later PR coordinates flipping this alongside the program's global
	// write-flip switch (plan residual item 5). Route tests set this directly
	// (matching how other tests mutate deps.Forge/deps.Reader).
	GateResultsWritable bool
	// FindingsRecomputer drives the findings gate's own producer (ENT-1255) on
	// this process's one trigger site: right after a review's comments/summary
	// publish atomically (reviewCommentsAtomicExec) — "agent-review
	// completion". nil (the default, and every test that doesn't wire it)
	// skips the call entirely; the review publish itself is unaffected either
	// way (best-effort, matching trailApprovalSyncReeval's own posture). The
	// repo-activity worker's branch-push trigger is a separate call site
	// (internal/trailforgeevents.Processor.SetFindingsRecomputer) — the same
	// findingsgate.Recomputer implementation, wired independently in each
	// process since neither shares the other's dependencies.
	FindingsRecomputer FindingsRecomputer
	// TrailWatchPresence is the per-connection lifecycle seam for the trail events
	// SSE stream (open on connect, bump on heartbeat, close on disconnect), keyed by
	// (trail, user, connection). ENT-1205 (watcher presence) will implement it to
	// record who is watching a trail; presence itself is out of scope here. nil (the
	// default, and every current caller) → the stream runs with no presence bookkeeping.
	TrailWatchPresence TrailWatchPresence
	// RefEventsNATS is the api process's connection to the regional NATS
	// cluster backing the live ref-change SSE stream (GET
	// /repos/{repo_id}/refs/events) — see internal/refstream and
	// ref_events_sse.go. This is the api process's first-ever NATS
	// dependency, dialed only when config.ActivityAPIConfig.RefEventsStreamEnabled
	// is set (internal/server/api.go); nil (the default, and every test that
	// doesn't wire it) degrades the route to 503 rather than leaving it
	// silently broken.
	RefEventsNATS *nats.Conn
	// YjsEngine is the yjs-engine sidecar client (ENT-1231). nil means the
	// merge route returns 503 — set after construction, like Snapshot.
	YjsEngine yjsengine.Client
}

// Read-through cache bounds. Entries are immutable for a fixed branch tip (the tip
// pins the history), so the TTL is memory management, not a correctness window.
const (
	commitCacheMax     = 8192
	commitCacheTTL     = 5 * time.Minute
	branchSHAsCacheMax = 4096
	branchSHAsCacheTTL = 5 * time.Minute
	// contributorsCache bounds the branch-delta contributor sets. Entries are
	// immutable for a resolved tip pair, so the TTL is memory management.
	contributorsCacheMax = 4096
	contributorsCacheTTL = 5 * time.Minute
	// commitMsgCacheMax bounds the immutable (repo,sha)→message cache. No TTL: a
	// commit's message never changes.
	commitMsgCacheMax = 16384
)

// NewUserActivityDeps assembles the user-activity HTTP deps. reader is the
// shared authz.Reader backing the /me read-time access filter; repoSt maps the
// repo-filter params to origin keys (nil in a deployment without a local repo
// store — filters then match placement ids only).
func NewUserActivityDeps(cfg config.Common, authn *auth.Authenticator, reader *authz.Reader, ready []ReadyCheck, st *store.UserStore, repoSt *store.RepoStore) *UserActivityDeps {
	deps := &UserActivityDeps{baseDeps: baseDeps{Config: cfg, Authenticator: authn, Reader: reader, ReadyChecks: ready}, Store: st}
	if repoSt != nil {
		// Best-effort: a store blip degrades the filter to placement identity
		// (never fails the read) — the same fallback an unresolved repo gets.
		deps.ResolveOrigins = func(ctx context.Context, repoIDs []string) map[string]string {
			origins, err := repoSt.RepoGroupIDs(ctx, repoIDs)
			if err != nil {
				return map[string]string{}
			}
			return origins
		}
		// Reverse of ResolveOrigins for the access gate: origin (repo_group) → this
		// region's local placement id. A store blip degrades to the repo_id-only
		// gate (never fails the read).
		deps.ResolveLocalPlacements = func(ctx context.Context, origins []string) map[string]string {
			byGroup, err := repoSt.ReposByGroup(ctx, origins, cfg.LocalClusterSlugs)
			if err != nil {
				return map[string]string{}
			}
			out := make(map[string]string, len(byGroup))
			for origin, row := range byGroup {
				out[origin] = row.ID
			}
			return out
		}
	}
	return deps
}

// NewRepoActivityDeps assembles the repo-activity HTTP deps. reader is the
// shared authz.Reader backing the repo/project access gates.
func NewRepoActivityDeps(cfg config.Common, authn *auth.Authenticator, reader *authz.Reader, ready []ReadyCheck, st *store.RepoStore, repoAPIBase string) *RepoActivityDeps {
	deps := &RepoActivityDeps{
		baseDeps:          baseDeps{Config: cfg, Authenticator: authn, Reader: reader, ReadyChecks: ready},
		Store:             st,
		RepoAPIBase:       repoAPIBase,
		commitCache:       newTTLCache[*repoapi.ListCommitsResponse](commitCacheMax, commitCacheTTL),
		branchSHAsCache:   newTTLCache[[]string](branchSHAsCacheMax, branchSHAsCacheTTL),
		contributorsCache: newTTLCache[[]CompareContributor](contributorsCacheMax, contributorsCacheTTL),
		Forge:             trailforge.NewNoop(),
	}
	// Commit-message read-through: resolve SHAs through entiredb's batch endpoint
	// over a fresh per-request content client (bearer-forwarding), behind the
	// immutable shared cache. Read-through disabled (no base) → empty messages.
	deps.commitMsgs = commitmsg.NewReader(func(ctx context.Context, repoID string, shas []string) (map[string]repoapi.Commit, error) {
		if deps.RepoAPIBase == "" {
			return map[string]repoapi.Commit{}, nil
		}
		return repoContentClient(ctx, deps).BatchCommits(ctx, deps.RepoAPIBase, repoID, shas, false)
	}, commitMsgCacheMax)
	return deps
}

// ReadyCheck is a named readiness probe for /readyz.
type ReadyCheck struct {
	Name  string
	Check func(ctx context.Context) error
}

// Router holds the chi mux, Huma API, and the readiness checks.
type Router struct {
	Mux         *chi.Mux
	API         huma.API
	readyChecks []ReadyCheck
}

// newRouter builds the chi mux + Huma API + health endpoints shared by both
// services. Each service then registers its own operations on r.API.
func newRouter(base baseDeps, title, description string) *Router {
	mux := chi.NewMux()
	// Per-IP front-door throttle, outermost so a rejected request does the least
	// work. It keys on the true client IP (Cf-Connecting-Ip behind the edge), read
	// before RealIP rewrites RemoteAddr. nil in tests, which share one loopback IP.
	if base.RateLimiter != nil {
		mux.Use(base.RateLimiter.Middleware)
	}
	mux.Use(middleware.RequestID)
	mux.Use(middleware.RealIP)
	mux.Use(spanName)   // rename the otelhttp span to the matched route
	mux.Use(requestLog) // structured access log + request_id in log context
	mux.Use(middleware.Recoverer)
	mux.Use(timeoutExceptStreaming(30 * time.Second))
	mux.Use(gzipResponses()) // gzip local JSON responses (innermost, closest to the handlers)

	useCompactErrors()
	cfg := huma.DefaultConfig(title, "1.0.0")
	cfg.Info.Description = description
	// Declare the tag catalog (names + descriptions + display order) so the docs
	// group operations deliberately instead of alphabetising bare, undocumented
	// tags. Each operation's Tags value names one of these; see tags.go.
	cfg.Tags = apiTags
	// Log the real cause of a 5xx (with request_id) before the redacted body is
	// written; see logServerErrors / apiError.
	cfg.Transformers = append(cfg.Transformers, logServerErrors)
	cfg.Servers = []*huma.Server{{URL: APIBase, Description: "This service"}}
	cfg.Components.SecuritySchemes = map[string]*huma.SecurityScheme{
		"bearerAuth": {Type: "http", Scheme: "bearer", BearerFormat: "JWT",
			Description: "Bearer token from entire-core's device-code or STS flows."},
	}
	// Paths are relative to the mount; APIBase prepends via the mount and the
	// server URL, so docs/openapi resolve at /api/v1/docs and /api/v1/openapi.
	cfg.DocsPath = "/docs"
	cfg.OpenAPIPath = "/openapi"

	// The API lives on its own mux mounted at APIBase. chi strips APIBase before
	// dispatching, so operations registered at /me serve at /api/v1/me while the
	// spec keys stay bare (/me).
	apiMux := chi.NewMux()
	api := humachi.New(apiMux, cfg)
	mux.Mount(APIBase, apiMux)
	r := &Router{Mux: mux, API: api, readyChecks: base.ReadyChecks}
	r.registerHealth()
	return r
}

// NewActivityAPIRouter builds the activity HTTP surface served by the
// standalone activity-api process: health + /me/* (user store) + the
// repo/contributor/project aggregate endpoints (repo store), all on one Huma
// API so the binary exposes a single OpenAPI document. Readiness unions both
// stores' probes.
func NewActivityAPIRouter(repoDeps *RepoActivityDeps, userDeps *UserActivityDeps) *Router {
	base := repoDeps.baseDeps
	base.ReadyChecks = append(append([]ReadyCheck{}, repoDeps.ReadyChecks...), userDeps.ReadyChecks...)
	r := newRouter(base,
		"Entire API",
		"Activity reads for this region: the caller's commits, checkpoints, activity, and recap (/me/*, user store), plus repo, contributor, and project aggregates (repo store). Residency-safe pointers only — content via the Repo API. Cross-jurisdiction clients federate via GET /api/v1/experimental/me.")
	// Per-request PostHog capture (backend DAU/MAU). Registered before the
	// operations so huma bakes it into every one's middleware chain, wrapping the
	// per-operation auth so it can capture the resolved caller after the handler
	// runs. A nil/disabled client makes it a no-op.
	r.API.UseMiddleware(captureRequests(base.Analytics, string(base.Config.Jurisdiction)))
	registerExperimentalMe(r.API, userDeps)
	registerMe(r.API, repoDeps, userDeps)
	registerMeSessions(r.API, repoDeps, userDeps)
	registerPreferences(r.API, userDeps)
	registerRepoPreferences(r.API, repoDeps, userDeps)
	registerRepos(r.API, repoDeps)
	registerRepoCollaborators(r.API, repoDeps)
	registerRefEvents(r.API, repoDeps)
	registerSharedSessionRead(r.API, repoDeps)
	registerExperts(r.API, repoDeps)
	registerCachePRs(r.API, repoDeps)
	registerProjects(r.API, repoDeps)
	registerTrails(r.API, repoDeps)
	registerEditorSync(r.API, repoDeps)
	registerEditorUpdates(r.API, repoDeps)
	registerEditorContent(r.API, repoDeps)
	registerRunnerIssuer(r.API, repoDeps.RunnerIssuerPublisher, repoDeps.RunnerIssuerRoutePrefix)
	return r
}

// NewHealthRouter builds a router exposing only /healthz + /readyz, for the
// worker processes (the repo/user `serve` commands) that run background
// workers but serve no API surface. k8s probes still need a port to hit.
func NewHealthRouter(ready []ReadyCheck) *Router {
	return newRouter(baseDeps{ReadyChecks: ready},
		"Entire Activity (worker)",
		"Health probes for an activity worker process (ingester/forwarder); no API surface.")
}

// HTTPHandler returns the chi mux wrapped in OTel HTTP instrumentation, so the
// whole server is traced and each request gets a span named for its route.
func (r *Router) HTTPHandler() http.Handler { return instrument(r.Mux, "activity") }

func (r *Router) registerHealth() {
	r.Mux.Get("/healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	})
	r.Mux.Get("/readyz", func(w http.ResponseWriter, req *http.Request) {
		ctx, cancel := context.WithTimeout(req.Context(), 3*time.Second)
		defer cancel()
		for _, c := range r.readyChecks {
			if err := c.Check(ctx); err != nil {
				// Log the raw dependency error server-side; the response body
				// names only the failed component so a driver error can't leak
				// internal hostnames/ports/DSN fragments to the caller.
				slog.ErrorContext(ctx, "readyz: dependency check failed",
					slog.String("component", c.Name), slog.Any("error", err))
				w.WriteHeader(http.StatusServiceUnavailable)
				_, _ = w.Write([]byte("not ready: " + c.Name))
				return
			}
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ready"))
	})
}

// requireAuth resolves the caller via the Authenticator, attaches the Identity
// to the request context, and gates the caller on their live waitlist state
// (COR-940). 401 on an auth failure, 403 when waitlisted, 503 when the approval
// lookup is unavailable.
func requireAuth(api huma.API, deps *baseDeps) func(huma.Context, func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		id, err := deps.Authenticator.Authenticate(ctx.Context(), httpRequestFromHuma(ctx))
		if err != nil {
			// Hand the verify cause up to requestLog's per-request line (see
			// setAuthnRejectCause) — but only for a PRESENTED bearer: a failed
			// verification of a real credential is diagnostic; tokenless 401s
			// are routine internet noise and the status alone already says it.
			if auth.BearerToken(ctx.Header("Authorization")) != "" {
				setAuthnRejectCause(ctx.Context(), err)
			}
			_ = huma.WriteErr(api, ctx, http.StatusUnauthorized, "authentication required", err)
			return
		}
		// Stash the verified caller identity AND the raw bearer: content endpoints
		// (transcripts) read through to the regional Repo API on the caller's
		// behalf, forwarding this same token (accepted there as a jurisdiction
		// identity token, re-authorized live against SpiceDB).
		reqCtx := auth.WithIdentity(ctx.Context(), id)
		if tok := auth.BearerToken(ctx.Header("Authorization")); tok != "" {
			reqCtx = auth.WithBearer(reqCtx, tok)
		}
		recordCaller(reqCtx, id) // hand the caller up to the capture middleware (records blocked attempts too)
		// The waitlist gate is an account-onboarding concept; an automation
		// principal has no account id and is never subject to it (it is
		// provisioned by the automation token exchange, not the account
		// signup flow).
		if accountID, ok := id.Subject.AccountID(); ok {
			if enforceApproval(api, ctx, deps.Approval, reqCtx, accountID) {
				return
			}
		}
		next(huma.WithContext(ctx, reqCtx))
	}
}

// enforceApproval applies the waitlist gate to an already-authenticated caller
// (COR-940), returning true — after writing the response — when the request must
// not proceed. A nil checker is a no-op. Fail-closed: only an explicit approved
// verdict passes; waitlisted is 403, and anything else (unavailable, or a future
// verdict) is a retryable 503.
func enforceApproval(api huma.API, ctx huma.Context, approval *auth.ApprovalChecker, reqCtx context.Context, accountID string) bool {
	if approval == nil {
		return false
	}
	switch approval.Check(reqCtx, accountID) {
	case auth.VerdictApproved:
		return false
	case auth.VerdictWaitlisted:
		_ = huma.WriteErr(api, ctx, http.StatusForbidden, "waitlisted: your account is pending approval")
	default: // VerdictUnavailable, or any future verdict → fail closed, retryable
		_ = huma.WriteErr(api, ctx, http.StatusServiceUnavailable, "approval check temporarily unavailable")
	}
	return true
}

// optionalAuth attaches the caller's Identity + bearer when a valid token is
// present, but never 401s: a token-less (or invalid-token) request proceeds
// anonymously and the handler fail-closes on access. The shared-session
// transcript read is the only optional-auth route — the BFF calls it
// unauthenticated for an anonymous viewer. A caller who does present a valid
// token takes the live (authorized) branch and is waitlist-gated exactly like
// requireAuth; only the anonymous path bypasses the gate.
func optionalAuth(api huma.API, deps *baseDeps) func(huma.Context, func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		tok := auth.BearerToken(ctx.Header("Authorization"))
		if tok == "" {
			next(ctx) // anonymous: no identity in context
			return
		}
		id, err := deps.Authenticator.Authenticate(ctx.Context(), httpRequestFromHuma(ctx))
		if err != nil {
			next(ctx) // present-but-invalid token → treat as anonymous, not a hard 401
			return
		}
		reqCtx := auth.WithBearer(auth.WithIdentity(ctx.Context(), id), tok)
		recordCaller(reqCtx, id) // hand the caller up to the capture middleware
		if accountID, ok := id.Subject.AccountID(); ok {
			if enforceApproval(api, ctx, deps.Approval, reqCtx, accountID) {
				return
			}
		}
		next(huma.WithContext(ctx, reqCtx))
	}
}

// httpRequestFromHuma reconstructs the minimal http.Request the
// Authenticator needs from a Huma context (bearer only).
func httpRequestFromHuma(ctx huma.Context) *http.Request {
	req := &http.Request{Header: http.Header{}}
	if v := ctx.Header("Authorization"); v != "" {
		req.Header.Set("Authorization", v)
	}
	return req.WithContext(ctx.Context())
}

func nowMeta() Meta { return Meta{ServerTime: time.Now().UTC()} }

package httpapi

import (
	"encoding/json"
	"time"

	"github.com/entirehq/entire-api/internal/store"
)

// Wire types for the trails surface. Field names and null semantics are the
// spike's contract (spikes/trails-service, RFD-023) — the BFF proxy, frontend,
// and CLI parse these exact shapes. No field is ever omitted; nullables
// serialize as explicit null; JSON-array columns always render as arrays.

type trailAuthor struct {
	ID    string  `json:"id"`
	Login *string `json:"login"`
}

type trailReviewer struct {
	Login  string `json:"login"`
	Status string `json:"status"`
}

type TrailListItem struct {
	ID                 string          `json:"id"`
	Number             int             `json:"number"`
	Title              string          `json:"title"`
	Status             string          `json:"status"`
	Branch             *string         `json:"branch"`
	OriginalBranch     *string         `json:"originalBranch"`
	Base               string          `json:"base"`
	Type               string          `json:"type"`
	Priority           string          `json:"priority"`
	Author             *trailAuthor    `json:"author"`
	Assignees          []string        `json:"assignees"`
	Reviewers          []trailReviewer `json:"reviewers"`
	RequestedReviewers []string        `json:"requestedReviewers"`
	HasCodeChanges     bool            `json:"hasCodeChanges"`
	CommentCount       int             `json:"commentCount"`
	UnresolvedCount    int             `json:"unresolvedCount"`
	CreatedAt          string          `json:"createdAt"`
	UpdatedAt          string          `json:"updatedAt"`
	MergedAt           *string         `json:"mergedAt"`
	Phase              *string         `json:"phase"`
}

// TrailsListResponse is the API-standard list envelope (ledger §3): `items` +
// an opaque `nextPageToken` (null when there is no further page). `repo` is
// dropped — the caller already has it from the path. totalCount (ENT-1185) is
// the filtered result set's total row count, identical across every page of
// the same request.
type TrailsListResponse struct {
	Items         []TrailListItem `json:"items"`
	NextPageToken *string         `json:"nextPageToken"`
	TotalCount    int             `json:"totalCount"`
}

// TrailDetailResponse is the single-trail detail envelope: every TrailListItem
// field plus the detail-only bodyDocument (trail body editor document),
// monitors (trend-enriched monitor results, same shape as GET .../monitors),
// and the merge/compare SHA triple. mergeBaseSha/baseSha/headSha are
// store-authoritative (unlike checkpoints/checkpointCount/hasWritePermission,
// which are deliberately absent here — the BFF composes those from the
// git/checkpoint plane and a GitHub install check) and drive the BFF's /files
// snapshot-refs path and mergeability, same as trailUpdateJSON's SHA triple.
type TrailDetailResponse struct {
	TrailListItem
	BodyDocument trailBodyDocumentJSON  `json:"bodyDocument"`
	Monitors     []trailMonitorItemJSON `json:"monitors"`
	MergeBaseSHA *string                `json:"mergeBaseSha"`
	BaseSHA      *string                `json:"baseSha"`
	HeadSHA      *string                `json:"headSha"`
	GhPrID       *int                   `json:"ghPrId,omitempty"`
}

// isoMillis renders JS Date.toISOString() format: UTC, millisecond precision, Z.
func isoMillis(t time.Time) string {
	return t.UTC().Format("2006-01-02T15:04:05.000Z")
}

// jsonStringArray tolerantly decodes a JSONB column that should hold a string
// array: non-array/corrupt values and non-string elements are dropped (spike
// parity — legacy data may hold garbage).
func jsonStringArray(raw []byte) []string {
	out := []string{}
	var vals []any
	if len(raw) == 0 || json.Unmarshal(raw, &vals) != nil {
		return out
	}
	for _, v := range vals {
		if s, ok := v.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

// jsonReviewerArray tolerantly decodes the reviewers JSONB column: a
// non-array value renders as []. Per element, an element that doesn't decode
// as a trailReviewer object (e.g. a bare number) is dropped rather than
// collapsing the whole array; unknown fields on an otherwise-valid object
// drop silently (json.Unmarshal's default behavior).
func jsonReviewerArray(raw []byte) []trailReviewer {
	out := []trailReviewer{}
	if len(raw) == 0 {
		return out
	}
	var elems []json.RawMessage
	if json.Unmarshal(raw, &elems) != nil {
		return out
	}
	for _, elem := range elems {
		var r trailReviewer
		if json.Unmarshal(elem, &r) == nil {
			out = append(out, r)
		}
	}
	return out
}

// deriveTrailPhase is the spike's trail-phase.ts lifted to Go (RFD-023: phase
// derivation moves with the domain). Only open trails have a phase (nil
// otherwise): reviewing when explicitly in_review or a reviewer is assigned,
// building once the branch has code changes (or legacy in_progress), planning
// before that.
func deriveTrailPhase(status string, hasCodeChanges bool, reviewerCount, requestedReviewerCount int) *string {
	phase := func(p string) *string { return &p }
	if status == "in_review" {
		return phase("reviewing")
	}
	if status != "open" && status != "in_progress" {
		return nil
	}
	if reviewerCount > 0 || requestedReviewerCount > 0 {
		return phase("reviewing")
	}
	if status == "in_progress" || hasCodeChanges {
		return phase("building")
	}
	return phase("planning")
}

// toTrailListItem maps a store row to the wire shape. logins maps author
// account ULIDs to GitHub logins (resolution is best-effort: a missing entry
// yields author.login = null, never an error).
func toTrailListItem(row store.TrailListRow, logins map[string]string) TrailListItem {
	// branch and original_branch ride the wire raw (null for an empty column),
	// matching the legacy list shape: the BFF derives the history branch itself
	// via branch ?? original_branch, so a renamed/removed branch (branch null,
	// original_branch set) keeps its fallback there.
	branch := strPtr(row.Branch)
	originalBranch := strPtr(row.OriginalBranch)
	priority := row.Priority
	if priority == "" {
		priority = "none"
	}
	var author *trailAuthor
	if row.AuthorAccountID != "" {
		author = &trailAuthor{ID: row.AuthorAccountID}
		if login, ok := logins[row.AuthorAccountID]; ok && login != "" {
			author.Login = &login
		}
	}
	var mergedAt *string
	if row.MergedAt != nil {
		s := isoMillis(*row.MergedAt)
		mergedAt = &s
	}
	reviewers := jsonReviewerArray(row.Reviewers)
	requested := jsonStringArray(row.RequestedReviewers)
	return TrailListItem{
		ID: row.ID, Number: row.Number, Title: row.Title, Status: row.Status,
		Branch: branch, OriginalBranch: originalBranch, Base: row.Base, Type: row.Type, Priority: priority,
		Author: author, Assignees: jsonStringArray(row.Assignees),
		Reviewers: reviewers, RequestedReviewers: requested,
		HasCodeChanges: row.HasCodeChanges,
		CommentCount:   row.CommentCount, UnresolvedCount: row.UnresolvedCount,
		CreatedAt: isoMillis(row.CreatedAt), UpdatedAt: isoMillis(row.UpdatedAt),
		MergedAt: mergedAt,
		Phase:    deriveTrailPhase(row.Status, row.HasCodeChanges, len(reviewers), len(requested)),
	}
}

package httpapi

// Trails surface (RFD-023 trails-native port, PR 1: walking skeleton reads).
//
// The read routes are dual-registered under TWO addressing schemes (ID-001):
//   - /trails/{host}/{owner}/{repo}/... — legacy wire-parity (requireTrailsAccess).
//   - /repos/{repo_id}/trails/...       — platform-standard opaque-id scheme
//     (requireTrailsAccessByID).
//
// Neither uses requireRepoAccess's distinct 403/404/503 gate: both resolve to a
// repoID, check the SpiceDB pull permission, then the trails product toggle,
// and collapse every negative (unknown repo, denied repo, trails disabled) to
// one 404 — a caller can never distinguish them (existence-hiding, spike
// parity). trailsAccessAllowed holds the shared decision; only how repoID is
// obtained (full_name resolution vs. the {repo_id} path param) differs.
// Writes stay single-addressed (host-path only) until PR 2 twins them too.

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/danielgtaylor/huma/v2"
	"github.com/oklog/ulid/v2"

	"github.com/entirehq/entire-api/internal/auth"
	"github.com/entirehq/entire-api/internal/httpapi/editorjson"
	"github.com/entirehq/entire-api/internal/httpapi/monitorenrich"
	"github.com/entirehq/entire-api/internal/store"
)

// validTrailsHosts is the closed set of forge-host slugs the legacy surface
// accepts (unknown slugs are a 400, wire parity with the legacy service).
var validTrailsHosts = map[string]bool{"gh": true, "et": true}

// resolvableTrailsHosts is the subset of valid hosts that can actually resolve
// to a repo in this cell. full_name rows ("owner/repo") carry no forge host,
// so a lookup that ignored the host could hand one forge's request another
// forge's repo if two ever share a name. Every resolvable row today is a
// GitHub mirror, so gh resolves and et fails closed into the collapsed 404
// until native repos get a forge-scoped naming source (host column or
// per-forge meta) — extend resolution deliberately then, don't widen this set.
var resolvableTrailsHosts = map[string]bool{"gh": true}

type trailsRepoKey struct{}

type resolvedTrailsRepo struct {
	repoID   string
	fullName string
}

// trailsAccessAllowed is the shared trails-gate decision once repoID is known:
// the SpiceDB permission check (pull for reads, push for writes), then the
// trails product toggle. It returns (true, nil) to admit, (false, nil) for the
// collapsed 404 (denied or disabled — the callers can't tell them apart on the
// wire), or a non-nil error for an infra failure (checker/SpiceDB/store), which
// the caller maps via writeAccessErr. TrailsEnabled's
// COALESCE(bool_or(...) FILTER(...), false) aggregate (see store/trails.go)
// always yields one row, even for a repoID with zero repo_setting_kv rows — so
// an unknown-but-well-formed repoID reads as disabled (false, nil) here, not a
// store error, and falls into the same 404.
func trailsAccessAllowed(ctx context.Context, deps *RepoActivityDeps, repoID, permission string) (bool, error) {
	allowed, err := repoPermissionAllowed(ctx, deps, repoID, permission)
	if err != nil || !allowed {
		return allowed, err
	}
	enabled, err := deps.Store.TrailsEnabled(ctx, repoID)
	if err != nil {
		return false, huma.Error500InternalServerError("store: trails toggle", err)
	}
	return enabled, nil
}

// requireTrailsAccess gates the READ trails routes (repo.pull).
func requireTrailsAccess(api huma.API, deps *RepoActivityDeps) opMiddleware {
	return requireTrailsAccessWithPermission(api, deps, permRepoRead)
}

// requireTrailsWriteAccess gates the WRITE trails routes (create/update/delete)
// on repo.push instead of repo.pull — identical host/full-name resolution and
// collapsed-404 semantics, just a stronger permission. Two named gates (not one
// caller-supplied-permission gate) keep "push is stronger than pull" visible at
// the registration site, matching requireRepoAccess/requireRepoPush's shape.
func requireTrailsWriteAccess(api huma.API, deps *RepoActivityDeps) opMiddleware {
	return requireTrailsAccessWithPermission(api, deps, permRepoWrite)
}

func requireTrailsAccessWithPermission(api huma.API, deps *RepoActivityDeps, permission string) opMiddleware {
	return func(hctx huma.Context, next func(huma.Context)) {
		ctx := hctx.Context()
		if !validTrailsHosts[hctx.Param("host")] {
			_ = huma.WriteErr(api, hctx, http.StatusBadRequest, "invalid host (must be one of: gh, et)")
			return
		}
		fullName := hctx.Param("owner") + "/" + hctx.Param("repo")
		var (
			repoID string
			found  bool
		)
		if resolvableTrailsHosts[hctx.Param("host")] {
			var err error
			repoID, found, err = deps.Store.RepoIDByFullName(ctx, fullName)
			if err != nil {
				_ = huma.WriteErr(api, hctx, http.StatusInternalServerError, "store: resolve repo", err)
				return
			}
		}
		if found {
			ok, err := trailsAccessAllowed(ctx, deps, repoID, permission)
			if err != nil {
				writeAccessErr(api, hctx, err)
				return
			}
			if ok {
				next(huma.WithValue(hctx, trailsRepoKey{}, resolvedTrailsRepo{repoID: repoID, fullName: fullName}))
				return
			}
		}
		_ = huma.WriteErr(api, hctx, http.StatusNotFound, "repository not found")
	}
}

// requireTrailsAccessByID is the {repo_id}-addressed twin of requireTrailsAccess
// (ID-001 dual-addressing): repoID comes straight from the path param, so there
// is no full_name resolution step, but the access decision (trailsAccessAllowed)
// and its collapsed 404 are identical. The list envelope dropped `repo` (see
// TrailsListResponse), so no read handler needs fullName — resolvedTrailsRepo's
// fullName is left empty for this scheme.
func requireTrailsAccessByID(api huma.API, deps *RepoActivityDeps) opMiddleware {
	return func(hctx huma.Context, next func(huma.Context)) {
		ctx := hctx.Context()
		repoID := hctx.Param("repo_id")
		ok, err := trailsAccessAllowed(ctx, deps, repoID, permRepoRead)
		if err != nil {
			writeAccessErr(api, hctx, err)
			return
		}
		if ok {
			next(huma.WithValue(hctx, trailsRepoKey{}, resolvedTrailsRepo{repoID: repoID}))
			return
		}
		_ = huma.WriteErr(api, hctx, http.StatusNotFound, "repository not found")
	}
}

func trailsRepoFromContext(ctx context.Context) (resolvedTrailsRepo, error) {
	rep, ok := ctx.Value(trailsRepoKey{}).(resolvedTrailsRepo)
	if !ok {
		return resolvedTrailsRepo{}, huma.Error500InternalServerError("trails: gate did not run")
	}
	return rep, nil
}

type TrailsRepoInput struct {
	Host  string `path:"host" doc:"Forge host slug (gh or et)"`
	Owner string `path:"owner" doc:"Repo owner"`
	Repo  string `path:"repo" doc:"Repo name"`
}

// TrailsRepoIDInput is the {repo_id}-addressed twin of TrailsRepoInput
// (ID-001): same shape as the platform-standard /repos/{repo_id}/... routes
// (e.g. RepoMetaInput).
type TrailsRepoIDInput struct {
	RepoID string `path:"repo_id" doc:"Repo id (ULID)"`
}

// trailsListDefaultPageSize / trailsListMaxPageSize bound the list route's
// pageSize query param (ledger §3): default 50, clamp to 1..100. PAGE-002: the
// minimum/maximum tags advertise the clamp in the OpenAPI spec (clampLimit
// still enforces it in code, so an out-of-range value is clamped, not rejected).
const (
	trailsListDefaultPageSize = 50
	trailsListMaxPageSize     = 100
)

// TrailsListFilterParams is the optional server-side filter surface shared by
// both list operations (ID-001 dual-addressing), embedded into each input.
// Every param is optional and additive: absent = no filter (current behaviour),
// so the endpoint is dark until a caller passes filters. An "is" param matches
// any value, its `Not` twin excludes all of them. status/priority/type match the
// column; assignee matches a stored GitHub login (assignees are login-keyed);
// author matches an account ULID (the one account-keyed actor column — a
// login→account resolver so a caller can filter author by login is a deferred
// follow-up); phase is derived server-side; search is a case-insensitive
// substring over title/branch/originalBranch. displayStatus is the BFF's
// public TrailDisplayStatus vocabulary (draft|planning|building|reviewing|
// merged|closed) — see store.TrailListFilters' doc comment for why it composes
// as one OR'd condition instead of riding the status/phase params above.
//
// Multi-value params carry `,explode` (the package convention, pinned by
// query_explode_test.go): a repeated param (?status=a&status=b) parses every
// value instead of silently keeping only the first. toStore also splits each
// value on commas, so the comma-separated form (?status=a,b) the BFF forwards
// works identically.
type TrailsListFilterParams struct {
	Status      []string `query:"status,explode" doc:"Match any of these statuses (repeatable or comma-separated)"`
	StatusNot   []string `query:"statusNot,explode" doc:"Exclude these statuses (repeatable or comma-separated)"`
	Priority    []string `query:"priority,explode" doc:"Match any of these priorities (repeatable or comma-separated)"`
	PriorityNot []string `query:"priorityNot,explode" doc:"Exclude these priorities (repeatable or comma-separated)"`
	Type        []string `query:"type,explode" doc:"Match any of these types (repeatable or comma-separated)"`
	TypeNot     []string `query:"typeNot,explode" doc:"Exclude these types (repeatable or comma-separated)"`
	Author      []string `query:"author,explode" doc:"Match any of these author account ULIDs (repeatable or comma-separated)"`
	AuthorNot   []string `query:"authorNot,explode" doc:"Exclude these author account ULIDs (repeatable or comma-separated)"`
	Assignee    []string `query:"assignee,explode" doc:"Match any of these assignee logins (repeatable or comma-separated)"`
	AssigneeNot []string `query:"assigneeNot,explode" doc:"Exclude these assignee logins (repeatable or comma-separated)"`
	Phase       []string `query:"phase,explode" doc:"Match any of these phases: planning, building, reviewing (repeatable or comma-separated)"`
	PhaseNot    []string `query:"phaseNot,explode" doc:"Exclude these phases (repeatable or comma-separated)"`
	// DisplayStatus/DisplayStatusNot carry the BFF's TrailDisplayStatus values
	// (draft|planning|building|reviewing|merged|closed — no "open"): additive to,
	// not a replacement for, status/statusNot/phase/phaseNot above.
	DisplayStatus    []string `query:"displayStatus,explode" doc:"Match any of these display statuses: draft, planning, building, reviewing, merged, closed (repeatable or comma-separated)"`
	DisplayStatusNot []string `query:"displayStatusNot,explode" doc:"Exclude these display statuses (repeatable or comma-separated)"`
	Search           string   `query:"search" doc:"Case-insensitive substring over title, branch, and original branch"`
}

func (p TrailsListFilterParams) toStore() store.TrailListFilters {
	return store.TrailListFilters{
		Status: splitCSV(p.Status), StatusNot: splitCSV(p.StatusNot),
		Priority: splitCSV(p.Priority), PriorityNot: splitCSV(p.PriorityNot),
		Type: splitCSV(p.Type), TypeNot: splitCSV(p.TypeNot),
		Author: splitCSV(p.Author), AuthorNot: splitCSV(p.AuthorNot),
		Assignee: splitCSV(p.Assignee), AssigneeNot: splitCSV(p.AssigneeNot),
		Phase: splitCSV(p.Phase), PhaseNot: splitCSV(p.PhaseNot),
		DisplayStatus: splitCSV(p.DisplayStatus), DisplayStatusNot: splitCSV(p.DisplayStatusNot),
		Search: p.Search,
	}
}

// splitCSV flattens `,explode` query values into their individual entries: each
// element is split on commas, trimmed, and empties dropped — so a repeated param
// (?x=a&x=b), a comma-separated one (?x=a,b), and any mix parse the same. Mirrors
// the BFF's splitMulti. Returns nil for no entries (applies no filter).
func splitCSV(vals []string) []string {
	out := make([]string, 0, len(vals))
	for _, v := range vals {
		for _, part := range strings.Split(v, ",") {
			if part = strings.TrimSpace(part); part != "" {
				out = append(out, part)
			}
		}
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

