// --- list pagination cursor (opaque base64 over (updatedAt, id)) -------

// trailsCursor is the wire shape of the list route's pageToken: an opaque
// base64 blob wrapping the keyset position, same shape as
// encodeSessionsCursor/decodeSessionsCursor (checkpointapi.go) but with its
// own type — the two surfaces' cursors are not interchangeable.
type trailsCursor struct {
	UpdatedAt string `json:"updatedAt"`
	ID        string `json:"id"`
}

// encodeTrailsPageToken builds the opaque pageToken for the row a page ends
// on, so the next request's pageToken picks up immediately after it.
func encodeTrailsPageToken(updatedAt time.Time, id string) string {
	b, _ := json.Marshal(trailsCursor{UpdatedAt: updatedAt.Format(time.RFC3339Nano), ID: id})
	return base64.RawURLEncoding.EncodeToString(b)
}

// decodeTrailsPageToken decodes a pageToken into a store.TrailCursor. An
// empty token is the first page (nil cursor, nil error); anything present
// but unparseable is a caller error the handler turns into a 400 — unlike
// decodeSessionsCursor, a bad trails pageToken is never silently treated as
// the first page.
func decodeTrailsPageToken(token string) (*store.TrailCursor, error) {
	if token == "" {
		return nil, nil
	}
	raw, err := base64.RawURLEncoding.DecodeString(token)
	if err != nil {
		return nil, err
	}
	var c trailsCursor
	if err := json.Unmarshal(raw, &c); err != nil {
		return nil, err
	}
	if c.ID == "" {
		return nil, errors.New("pageToken: missing id")
	}
	if _, err := ulid.Parse(c.ID); err != nil {
		return nil, fmt.Errorf("pageToken: invalid id: %w", err)
	}
	t, err := time.Parse(time.RFC3339Nano, c.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &store.TrailCursor{UpdatedAt: t, ID: c.ID}, nil
}

// resolveAuthorLogins best-effort maps author account ULIDs to GitHub logins.
// Resolution failures (or a nil resolver) degrade to unresolved logins, never
// to a request error — login is decoration, the trail data is the payload.
// Delegates to resolveAuthorUsernames for the dedupe + batch lookup + logging
// (a resolve failure is logged there via slog.WarnContext, not swallowed silently).
func resolveAuthorLogins(ctx context.Context, deps *RepoActivityDeps, rows []store.TrailListRow) map[string]string {
	ids := make([]string, 0, len(rows))
	for _, r := range rows {
		if r.AuthorAccountID != "" {
			ids = append(ids, r.AuthorAccountID)
		}
	}
	return resolveAuthorUsernames(ctx, deps.AuthorUsernames, ids)
}

// trailsListCore is the list handler's shared body (ID-001 dual-addressing):
// both the {host}/{owner}/{repo} and {repo_id} operations delegate here,
// differing only in how repoID reached the context (the gate) and which input
// struct huma bound pageSize/pageToken from.
func trailsListCore(ctx context.Context, deps *RepoActivityDeps, pageSizeIn int, pageToken string, filters store.TrailListFilters) (*TrailsListOutput, error) {
	rep, err := trailsRepoFromContext(ctx)
	if err != nil {
		return nil, err
	}
	after, err := decodeTrailsPageToken(pageToken)
	if err != nil {
		return nil, huma.Error400BadRequest("invalid pageToken", err)
	}
	pageSize := clampLimit(pageSizeIn, trailsListDefaultPageSize, trailsListMaxPageSize)
	rows, totalCount, err := deps.Store.ListTrailsByRepo(ctx, rep.repoID, pageSize, after, filters)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: list trails", err)
	}
	// The store fetches pageSize+1 rows unmodified; a full extra row means
	// there's a next page — trim it off and cursor the token from the last
	// *returned* (post-trim) row.
	var nextPageToken *string
	if len(rows) > pageSize {
		rows = rows[:pageSize]
		last := rows[len(rows)-1]
		token := encodeTrailsPageToken(last.UpdatedAt, last.ID)
		nextPageToken = &token
	}
	logins := resolveAuthorLogins(ctx, deps, rows)
	items := make([]TrailListItem, 0, len(rows))
	for _, r := range rows {
		items = append(items, toTrailListItem(r, logins))
	}
	out := &TrailsListOutput{}
	out.Body = TrailsListResponse{Items: items, NextPageToken: nextPageToken, TotalCount: totalCount}
	return out, nil
}

// trailsStatsCore is the stats handler's shared body (ID-001 dual-addressing).
func trailsStatsCore(ctx context.Context, deps *RepoActivityDeps) (*TrailsStatsOutput, error) {
	rep, err := trailsRepoFromContext(ctx)
	if err != nil {
		return nil, err
	}
	counts, err := deps.Store.CountTrailsByStatus(ctx, rep.repoID)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: trail stats", err)
	}
	out := &TrailsStatsOutput{}
	out.Body = counts
	return out, nil
}

// trailsLinkedBranchesCore is the linked-branches handler's shared body
