// TrailBodyDocumentEnsureInput addresses the trail whose body document to
// ensure (ENT-1231): host-path addressing only — the caller is the BFF ws
// route, which is host-addressed (single-addressed like the ingest surface;
// ID-001 dual-addressing exempts internal-caller endpoints).
type TrailBodyDocumentEnsureInput struct {
	Host   string `path:"host"`
	Owner  string `path:"owner"`
	Repo   string `path:"repo"`
	Number string `path:"number"`
}

// TrailBodyDocumentEnsureOutput always answers 201, whether the call minted
// the document, restored a soft-deleted one, or merely resolved an
// already-linked document on an idempotent replay (HTTP-005: creates never
// report 200). Status is read by huma via reflection (FieldByName("Status"))
// and, once present, is what huma passes to WriteHeader — it does NOT fall
// back to op.DefaultStatus for an unset (zero) value, so every return path
// sets Status explicitly (relying on the zero value happened to render as 200
// only because gzhttp's ResponseWriter defers WriteHeader and Go's net/http
// then defaults an unsent header to 200 on first Write — an incidental
// behavior of the current middleware stack, not a documented fallback).
// ensureOp.DefaultStatus is set to 201 (HTTP-002) so the create path is
// actually documented in the OpenAPI spec. Location is likewise unconditional
// (HTTP-003): since every response is 201, every response carries a Location
// addressing the resolved document's sync resource by its authoritative key
// — never gated on whether this particular call is what minted the row.
type TrailBodyDocumentEnsureOutput struct {
	Status   int    `json:"-"`
	Location string `header:"Location"`
	Body     trailBodyDocumentJSON
}

// trailBodyDocumentSyncLocation builds the Location header value for a
// resolved (not necessarily just-minted) body editor document, addressing its
// sync resource by its authoritative key.
func trailBodyDocumentSyncLocation(documentKey string) string {
	return APIBase + "/editor-documents/" + url.PathEscape(documentKey) + "/sync"
}

// trailBodyDocumentForDetail reads the trail's body editor document without
// creating one — unlike EnsureTrailBodyDocument, a GET must not have the side
// effect of minting a row. row.BodyEditorDocumentID is checked FIRST and by id
// (EditorDocumentByID): an imported trail's document keeps its legacy
// (PlanetScale) document_key verbatim, so the deterministic live key
// ("trail:<id>:body", the same key resolveTrailDelete falls back to) would
// miss it entirely. Only a trail with neither a linked id nor a live-keyed
// document (never touched by the editor) falls through to the empty-document
// shape toTrailBodyDocumentJSON renders for a zero-content row.
func trailBodyDocumentForDetail(ctx context.Context, deps *RepoActivityDeps, row store.TrailDetailRow) (trailBodyDocumentJSON, error) {
	key := "trail:" + row.ID + ":body"
	if row.BodyEditorDocumentID != "" {
		doc, ok, err := deps.Store.EditorDocumentByID(ctx, row.BodyEditorDocumentID)
		if err != nil {
			return trailBodyDocumentJSON{}, err
		}
		if ok {
			return toTrailBodyDocumentJSON(doc), nil
		}
	}
	doc, ok, err := deps.Store.EditorDocumentByKey(ctx, key)
	if err != nil {
		return trailBodyDocumentJSON{}, err
	}
	if !ok {
		return trailBodyDocumentJSON{
			DocumentKey:   key,
			SchemaVersion: 1,
			ContentJSON:   json.RawMessage(editorjson.EmptyEditorJSON()),
			UpdatedAt:     isoMillis(row.UpdatedAt),
		}, nil
	}
	return toTrailBodyDocumentJSON(doc), nil
}

// trailDetailCore is the detail-by-number handler's shared body (ID-001
// dual-addressing): the list item's fields plus the body document and monitor
// results (the latter via trailMonitorsCore's own mapping, so trend/history/
// evaluating logic isn't duplicated here).
func trailDetailCore(ctx context.Context, deps *RepoActivityDeps, repoID, numberRaw string) (*TrailDetailOutput, error) {
	row, err := resolveTrailByNumberParam(ctx, deps, repoID, numberRaw)
	if err != nil {
		return nil, err
	}
	logins := resolveAuthorLogins(ctx, deps, []store.TrailListRow{row.TrailListRow})
	bodyDoc, err := trailBodyDocumentForDetail(ctx, deps, row)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: trail body document", err)
	}
	monitorRows, err := deps.Store.ListMonitorResults(ctx, row.ID)
	if err != nil {
		return nil, huma.Error500InternalServerError("store: list monitor results", err)
	}
	enrichment := monitorenrich.GetTrailMonitorEnrichment(ctx, deps.Store, row.ID, monitorRows)
	monitors := make([]trailMonitorItemJSON, 0, len(monitorRows))
	for _, m := range monitorRows {
		e, ok := enrichment[m.Key]
		monitors = append(monitors, toTrailMonitorItemJSON(m, e, ok))
	}
	out := &TrailDetailOutput{}
	out.Body = TrailDetailResponse{
		TrailListItem: toTrailListItem(row.TrailListRow, logins),
		BodyDocument:  bodyDoc,
		Monitors:      monitors,
		MergeBaseSHA:  nullableString(row.MergeBaseSHA),
		BaseSHA:       nullableString(row.BaseSHA),
		HeadSHA:       nullableString(row.HeadSHA),
		GhPrID:        row.GhPrID,
	}
	return out, nil
}

func registerTrails(api huma.API, deps *RepoActivityDeps) {
	gate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsAccess(api, deps)}
	trailsOp := func(id, method, path, summary string) huma.Operation {
		return teamOp(id, method, path, summary, "trails", gate)
	}
	// repoIDGate is the {repo_id}-addressed twin (ID-001 dual-addressing, PR 1:
	// reads only — writes stay host-path-only until PR 2).
	repoIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsAccessByID(api, deps)}
	trailsByIDOp := func(id, method, path, summary string) huma.Operation {
		return teamOp(id, method, path, summary, "trails", repoIDGate)
	}

	huma.Register(api, trailsOp("trailsList", http.MethodGet,
		"/trails/{host}/{owner}/{repo}", "List a repo's trails"),
		func(ctx context.Context, in *TrailsListInput) (*TrailsListOutput, error) {
			return trailsListCore(ctx, deps, in.PageSize, in.PageToken, in.toStore())
		})

	huma.Register(api, trailsByIDOp("trailsListByRepoID", http.MethodGet,
		"/repos/{repo_id}/trails", "List a repo's trails (repo_id addressing)"),
		func(ctx context.Context, in *TrailsListByRepoIDInput) (*TrailsListOutput, error) {
			return trailsListCore(ctx, deps, in.PageSize, in.PageToken, in.toStore())
		})

	huma.Register(api, trailsOp("trailsStats", http.MethodGet,
		"/trails/{host}/{owner}/{repo}/stats", "Trail counts by status"),
		func(ctx context.Context, in *TrailsRepoInput) (*TrailsStatsOutput, error) {
			return trailsStatsCore(ctx, deps)
		})

	huma.Register(api, trailsByIDOp("trailsStatsByRepoID", http.MethodGet,
		"/repos/{repo_id}/trails/stats", "Trail counts by status (repo_id addressing)"),
		func(ctx context.Context, in *TrailsRepoIDInput) (*TrailsStatsOutput, error) {
			return trailsStatsCore(ctx, deps)
		})

	huma.Register(api, trailsOp("trailsLinkedBranches", http.MethodGet,
		"/trails/{host}/{owner}/{repo}/linked-branches", "Branches claimed by trails"),
		func(ctx context.Context, in *TrailsRepoInput) (*TrailsLinkedBranchesOutput, error) {
			return trailsLinkedBranchesCore(ctx, deps)
		})

	huma.Register(api, trailsByIDOp("trailsLinkedBranchesByRepoID", http.MethodGet,
		"/repos/{repo_id}/trails/linked-branches", "Branches claimed by trails (repo_id addressing)"),
		func(ctx context.Context, in *TrailsRepoIDInput) (*TrailsLinkedBranchesOutput, error) {
			return trailsLinkedBranchesCore(ctx, deps)
		})

	// trailDetailOp variants add 404 to the two detail ops below (an unknown
	// trail number 404s) — every other op registered above via trailsOp/
	// trailsByIDOp never fails past the collapsed-404 gate itself.
	trailDetailOp := func(id, method, path, summary string) huma.Operation {
		op := trailsOp(id, method, path, summary)
		op.Errors = withExtraErrors(op.Errors, http.StatusNotFound)
		return op
	}
	trailDetailByIDOp := func(id, method, path, summary string) huma.Operation {
		op := trailsByIDOp(id, method, path, summary)
		op.Errors = withExtraErrors(op.Errors, http.StatusNotFound)
		return op
	}

	huma.Register(api, trailDetailOp("trailDetail", http.MethodGet,
		"/trails/{host}/{owner}/{repo}/{number}", "Get a trail by number"),
		func(ctx context.Context, in *TrailDetailInput) (*TrailDetailOutput, error) {
			rep, err := trailsRepoFromContext(ctx)
			if err != nil {
				return nil, err
			}
			return trailDetailCore(ctx, deps, rep.repoID, in.Number)
		})

	huma.Register(api, trailDetailByIDOp("trailDetailByRepoID", http.MethodGet,
		"/repos/{repo_id}/trails/{number}", "Get a trail by number (repo_id addressing)"),
		func(ctx context.Context, in *TrailDetailByRepoIDInput) (*TrailDetailOutput, error) {
			rep, err := trailsRepoFromContext(ctx)
			if err != nil {
				return nil, err
			}
			return trailDetailCore(ctx, deps, rep.repoID, in.Number)
		})

	// Body-document ensure (ENT-1231): the BFF ws route calls this before
	// forwarding a websocket upgrade to the editor DO, so the document row
	// exists and its key is authoritative before any sync traffic. Read-gated
	// (repo.pull) DELIBERATELY, not write-gated: parity with the BFF ws
	// route's historical access semantics — anyone who may open the editor
	// may mint the (empty) row. The detail GET stays mint-free.
	ensureOp := trailsOp("trailBodyDocumentEnsure", http.MethodPost,
		"/trails/{host}/{owner}/{repo}/{number}/body-document/ensure",
		"Ensure a trail's body editor document exists")
	ensureOp.DefaultStatus = http.StatusCreated
	ensureOp.Errors = withExtraErrors(ensureOp.Errors, http.StatusNotFound, http.StatusConflict)
	huma.Register(api, ensureOp,
		func(ctx context.Context, in *TrailBodyDocumentEnsureInput) (*TrailBodyDocumentEnsureOutput, error) {
			rep, err := trailsRepoFromContext(ctx)
			if err != nil {
				return nil, err
			}
			// Backstop against a stale route or routing regression sending the
			// ensure call to a non-primary cell: minting here would fork one
			// trail body into two independent documents (ENT-1385). Gated on the
			// sole-processing-placement predicate, NOT the bare processing_primary
			// flag: an ungrouped repo is never stamped, so the bare flag would
			// refuse the one cell that does hold it.
			primary, err := deps.Store.IsSoleProcessingPlacement(ctx, rep.repoID)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: is sole processing placement", err)
			}
			if !primary {
				return nil, huma.Error409Conflict("this cell's placement is not the repo group's processing primary")
			}
			row, err := resolveTrailByNumberParam(ctx, deps, rep.repoID, in.Number)
			if err != nil {
				return nil, err
			}
			identity := auth.FromContext(ctx)
			if identity == nil {
				return nil, huma.Error401Unauthorized("authentication required")
			}
			// Linked-document resolution comes FIRST, by id — the same order as
			// trailBodyDocumentForDetail: an imported trail's document keeps its
			// legacy document_key, so the deterministic key EnsureTrailBodyDocument
			// looks up would miss it and mint a parallel empty row. A linked but
			// soft-deleted document falls through to the mint path (soft-delete
			// means "start clean" under the partial unique index).
			// Status is always 201 (HTTP-005: creates never report 200, even
			// on an idempotent replay that minted nothing) — and so is Location
			// (HTTP-003: every 201 this handler returns must carry one), derived
			// unconditionally from the resolved document's key rather than gated
			// on whether this call is what minted the row.
			if row.BodyEditorDocumentID != "" {
				doc, ok, err := deps.Store.EditorDocumentByID(ctx, row.BodyEditorDocumentID)
				if err != nil {
					return nil, huma.Error500InternalServerError("store: editor document by id", err)
				}
				if ok {
					return &TrailBodyDocumentEnsureOutput{
						Status:   http.StatusCreated,
						Location: trailBodyDocumentSyncLocation(doc.DocumentKey),
						Body:     toTrailBodyDocumentJSON(doc),
					}, nil
				}
			}
			// repo_trails' body-document actor column has no actor_ref sibling
			// (unlike reviews/review_comments), so an automation caller — with
			// no account id to attribute to — is refused rather than silently
			// written as an empty account id. identity was already resolved
			// above; reuse it instead of re-deriving from ctx.
			actorAccountID, ok := identity.Subject.AccountID()
			if !ok {
				return nil, huma.Error403Forbidden("automation principals cannot create a trail body document")
			}
			doc, _, err := deps.Store.EnsureTrailBodyDocument(ctx, store.EnsureTrailBodyDocumentInput{
				TrailID: row.ID, ActorAccountID: actorAccountID,
			})
			if err != nil {
				return nil, huma.Error500InternalServerError("store: ensure trail body document", err)
			}
			return &TrailBodyDocumentEnsureOutput{
				Status:   http.StatusCreated,
				Location: trailBodyDocumentSyncLocation(doc.DocumentKey),
				Body:     toTrailBodyDocumentJSON(doc),
			}, nil
		})

	registerTrailsWrites(api, deps)
	registerThreads(api, deps)
	registerThreadEventsStream(api, deps)
	registerReviews(api, deps)
	registerReviewReads(api, deps)
	registerTrailWatchers(api, deps)
	registerRunnerReads(api, deps)
	registerManualTrailRunnerLaunch(api, deps)
	registerReviewRerun(api, deps)
	registerRunnerIngest(api, deps)
	registerTrailsCommand(api, deps)
	registerTrailsAttachments(api, deps)
	registerTrailsDefinitions(api, deps)
	registerTrailsGateSettings(api, deps)
	registerTrailsGateDefinitions(api, deps)
	registerTrailsGates(api, deps)
	registerTrailsMergeability(api, deps)
	registerTrailsApprovals(api, deps)
	registerTrailsMerge(api, deps)
	registerTrailsTimeline(api, deps)
}

