// trail-assignees.ts's normalizeAssigneeLogins, ported verbatim: trim, drop
// blanks, de-duplicate case-insensitively while preserving first-seen casing
// and order.
func normalizeAssigneeLogins(logins []string) []string {
	out := []string{}
	seen := map[string]bool{}
	for _, login := range logins {
		trimmed := strings.TrimSpace(login)
		if trimmed == "" {
			continue
		}
		key := strings.ToLower(trimmed)
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, trimmed)
	}
	return out
}

// uniquePreserveOrder de-duplicates ss (exact string match, NOT
// case-insensitive) while preserving first-seen order — the update route's
// requested_reviewers handling (`Array.from(new Set(...))`, trail-update.ts),
// deliberately NOT run through normalizeAssigneeLogins's trim/casefold.
func uniquePreserveOrder(ss []string) []string {
	seen := map[string]bool{}
	out := make([]string, 0, len(ss))
	for _, s := range ss {
		if seen[s] {
			continue
		}
		seen[s] = true
		out = append(out, s)
	}
	return out
}

// ---- raw-JSON presence/type helpers ----
//
// rawPresent/rawAsString/rawAsStringSlice reproduce the spike's `!==
// undefined` / `typeof x === "string"` / `Array.isArray(x) && x.every(...)`
// runtime checks against an opaque json.RawMessage field. A field decodes to
// its Go zero value (empty string / nil-not-ok) whenever it is absent, JSON
// null, or the wrong JSON type — every caller below re-derives "present" via
// rawPresent (not the decoded value), matching the spike's presence checks.

// rawPresent reports whether the JSON key was present in the request body at
// all (any value, including explicit null) — the byte-level analogue of the
// spike's `!== undefined` checks.
func rawPresent(f json.RawMessage) bool { return len(f) > 0 }

// rawAsString decodes f as a JSON string. ok is false when f is absent, JSON
// null, or not a string — the caller then treats the value as "" for
// enum/truthy comparisons (which never match a valid enum member or a
// non-empty requirement anyway, so the net effect matches the spike's
// behavior for a wrongly-typed field).
func rawAsString(f json.RawMessage) (string, bool) {
	if len(f) == 0 || string(f) == "null" {
		return "", false
	}
	var s string
	if err := json.Unmarshal(f, &s); err != nil {
		return "", false
	}
	return s, true
}

// rawAsInt decodes f as a JSON integer (mirrors rawAsString's posture for a
// numeric field). ok is false when f is absent, JSON null, or not an integer
// JSON number — a fractional or non-numeric value decodes to (0, false), so the
// caller treats it as "not supplied" rather than silently truncating.
func rawAsInt(f json.RawMessage) (int, bool) {
	if len(f) == 0 || string(f) == "null" {
		return 0, false
	}
	var n int
	if err := json.Unmarshal(f, &n); err != nil {
		return 0, false
	}
	return n, true
}

// rawAsStringSlice decodes f as a JSON array of strings (mirrors
// `Array.isArray(x) && x.every(v => typeof v === "string")`). ok is false for
// an absent field, JSON null, a non-array value, or an array with any
// non-string element.
func rawAsStringSlice(f json.RawMessage) ([]string, bool) {
	if len(f) == 0 || string(f) == "null" {
		return nil, false
	}
	var raw []json.RawMessage
	if err := json.Unmarshal(f, &raw); err != nil {
		return nil, false
	}
	out := make([]string, 0, len(raw))
	for _, r := range raw {
		var s string
		if err := json.Unmarshal(r, &s); err != nil {
			return nil, false
		}
		out = append(out, s)
	}
	return out, true
}

// trailValidationError is the {message, status} pair validateCreateTrailBody
// / validateUpdateTrailBody return — status is always one of 400/422/503.
type trailValidationError struct {
	status  int
	message string
}

func (e *trailValidationError) humaError() error {
	switch e.status {
	case http.StatusUnprocessableEntity:
		return huma.Error422UnprocessableEntity(e.message)
	case http.StatusServiceUnavailable:
		return huma.Error503ServiceUnavailable(e.message)
	default:
		return huma.Error400BadRequest(e.message)
	}
}

