// trailCreateBody is POST /:host/:owner/:repo's body (trail-create.ts's
// CreateTrailBody).
// Every field carries `omitempty`: without it, Huma's schema reflection marks
// a json.RawMessage field required (any JSON value, including `{}`, then
// fails Huma's OWN schema validation — 422 "validation failed" — for every
// field this spec-optional body omits, before validateCreateTrailBody ever
// runs). `omitempty` makes the OpenAPI schema mark the field optional, which
// is what "may be absent" actually means here — the RawMessage's *value* is
// untouched by it (encoding/json's omitempty has no effect on decode, only
// on this struct's own encode, which this type is never used for).
type trailCreateBody struct {
	Title        json.RawMessage `json:"title,omitempty"`
	Body         json.RawMessage `json:"body,omitempty"`
	BranchName   json.RawMessage `json:"branchName,omitempty"`
	BranchAction json.RawMessage `json:"branchAction,omitempty"`
	Base         json.RawMessage `json:"base,omitempty"`
	Status       json.RawMessage `json:"status,omitempty"`
	Assignees    json.RawMessage `json:"assignees,omitempty"`
	Type         json.RawMessage `json:"type,omitempty"`
	Priority     json.RawMessage `json:"priority,omitempty"`
}

