// requireTrailsWriteAccessByID is the {repo_id}-addressed write gate. Unlike
// the read twin, write handlers need the repository full name for forge calls
// and lifecycle events, so an admitted repo ID is reverse-resolved before the
// handler runs. Authorization denials and a disabled trails toggle remain the
// same collapsed 404 as every trails route; a missing local metadata row after
// admission is an internal consistency failure.
func requireTrailsWriteAccessByID(api huma.API, deps *RepoActivityDeps) opMiddleware {
	return func(hctx huma.Context, next func(huma.Context)) {
		ctx := hctx.Context()
		repoID := hctx.Param("repo_id")
		ok, err := trailsAccessAllowed(ctx, deps, repoID, permRepoWrite)
		if err != nil {
			writeAccessErr(api, hctx, err)
			return
		}
		if !ok {
			_ = huma.WriteErr(api, hctx, http.StatusNotFound, "repository not found")
			return
		}

		metas, err := deps.Store.ListRepoMetas(ctx, []string{repoID})
		if err != nil {
			_ = huma.WriteErr(api, hctx, http.StatusInternalServerError, "store: resolve repo name", err)
			return
		}
		if len(metas) != 1 || metas[0].FullName == "" {
			_ = huma.WriteErr(api, hctx, http.StatusInternalServerError, "store: resolve repo name",
				fmt.Errorf("repo %s passed trails access but has no full name", repoID))
			return
		}
		next(huma.WithValue(hctx, trailsRepoKey{}, resolvedTrailsRepo{repoID: repoID, fullName: metas[0].FullName}))
	}
}

// registerTrailsWrites wires the create/update/delete routes onto the
// requireTrailsWriteAccess (push) gate. Called from registerTrails
// (trails.go) so every trails route (read + write) registers from one place.
func registerTrailsWrites(api huma.API, deps *RepoActivityDeps) {
	hostGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccess(api, deps)}
	byIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccessByID(api, deps)}
	writeOp := func(id, method, path, summary string, gate []opMiddleware) huma.Operation {
		return teamOp(id, method, path, summary, "trails", gate)
	}

	createOp := writeOp("trailsCreate", http.MethodPost,
		"/trails/{host}/{owner}/{repo}", "Create a trail", hostGate)
	createOp.DefaultStatus = http.StatusCreated
	// The create handler gates on repo resolution before ever reaching
	// create-specific logic — a denied/disabled/unresolvable repo 404s there,
	// so 404 is a real possible response that must be declared (HTTP-007
	// parity with the update/delete ops below).
	createOp.Errors = withExtraErrors(createOp.Errors, http.StatusConflict, http.StatusNotFound)
	huma.Register(api, createOp,
		func(ctx context.Context, in *TrailsRepoWriteInput) (*TrailsCreateOutput, error) {
			return resolveTrailCreate(ctx, deps, in.Body, func(_ resolvedTrailsRepo, number int) string {
				return fmt.Sprintf("%s/trails/%s/%s/%s/%d", APIBase, in.Host, in.Owner, in.Repo, number)
			})
		})
	createByIDOp := writeOp("trailsCreateByRepoID", http.MethodPost,
		"/repos/{repo_id}/trails", "Create a trail by repo id", byIDGate)
	createByIDOp.DefaultStatus = http.StatusCreated
	// See createOp's comment above: same repo-resolution 404 gate applies here.
	createByIDOp.Errors = withExtraErrors(createByIDOp.Errors, http.StatusConflict, http.StatusNotFound)
	huma.Register(api, createByIDOp,
		func(ctx context.Context, in *TrailsRepoIDWriteInput) (*TrailsCreateOutput, error) {
			return resolveTrailCreate(ctx, deps, in.Body, func(rep resolvedTrailsRepo, number int) string {
				return fmt.Sprintf("%s/repos/%s/trails/%d", APIBase, rep.repoID, number)
			})
		})

	// HTTP-007: all four number-addressed ops resolve the trail via
	// resolveTrailByNumberParam, which 404s on an unknown trail number — but
	// none of their Errors lists declared it, leaving a real response code
	// undocumented in the OpenAPI surface.
	updateOp := writeOp("trailsUpdate", http.MethodPatch,
		"/trails/{host}/{owner}/{repo}/{number}", "Update a trail's metadata", hostGate)
	updateOp.Errors = withExtraErrors(updateOp.Errors, http.StatusNotFound, http.StatusConflict, http.StatusUnprocessableEntity, http.StatusServiceUnavailable, http.StatusPreconditionFailed)
	huma.Register(api, updateOp,
		func(ctx context.Context, in *TrailsTrailUpdateInput) (*TrailsUpdateOutput, error) {
			return resolveTrailUpdate(ctx, deps, in.Number, in.Body, in.IfMatch)
		})
	updateByIDOp := writeOp("trailsUpdateByRepoID", http.MethodPatch,
		"/repos/{repo_id}/trails/{number}", "Update a trail's metadata by repo id", byIDGate)
	updateByIDOp.Errors = withExtraErrors(updateByIDOp.Errors, http.StatusNotFound, http.StatusConflict, http.StatusUnprocessableEntity, http.StatusServiceUnavailable, http.StatusPreconditionFailed)
	huma.Register(api, updateByIDOp,
		func(ctx context.Context, in *TrailsTrailByRepoIDUpdateInput) (*TrailsUpdateOutput, error) {
			return resolveTrailUpdate(ctx, deps, in.Number, in.Body, in.IfMatch)
		})

	deleteOp := writeOp("trailsDelete", http.MethodDelete,
		"/trails/{host}/{owner}/{repo}/{number}", "Delete a trail", hostGate)
	deleteOp.DefaultStatus = http.StatusNoContent
	deleteOp.Errors = withExtraErrors(deleteOp.Errors, http.StatusNotFound, http.StatusPreconditionFailed)
	huma.Register(api, deleteOp,
		func(ctx context.Context, in *TrailsTrailWriteInput) (*TrailsDeleteOutput, error) {
			return resolveTrailDelete(ctx, deps, in.Number, in.IfMatch)
		})
	deleteByIDOp := writeOp("trailsDeleteByRepoID", http.MethodDelete,
		"/repos/{repo_id}/trails/{number}", "Delete a trail by repo id", byIDGate)
	deleteByIDOp.DefaultStatus = http.StatusNoContent
	deleteByIDOp.Errors = withExtraErrors(deleteByIDOp.Errors, http.StatusNotFound, http.StatusPreconditionFailed)
	huma.Register(api, deleteByIDOp,
		func(ctx context.Context, in *TrailsTrailByRepoIDWriteInput) (*TrailsDeleteOutput, error) {
			return resolveTrailDelete(ctx, deps, in.Number, in.IfMatch)
		})
