// cleanupOrphanedBranch best-effort deletes a branch this handler just
// created via ForgeSync.CreateBranch when CreateTrail returns a genuine
// error, so the branch never gets persisted with a trail row to back it —
// correctness fix: forge branch orphan on create failure. Must NOT be called
// when CreateTrail resolves to an existing row (Created:false, the
// lost-branch-race dedup/409 path): that branch belongs to the concurrent
// request that won the race and is backing a live, already-persisted trail
// row — deleting it here would destroy that sibling's branch out from under
// it. A DeleteBranch failure is logged, never surfaced to the caller: the
// original create failure is already the response.
func cleanupOrphanedBranch(ctx context.Context, fw trailforge.ForgeSync, caller trailforge.Caller, repo trailforge.Repo, branch string) {
	del := fw.DeleteBranch(ctx, caller, trailforge.DeleteBranchArgs{Repo: repo, Branch: branch})
	if !del.OK {
		slog.ErrorContext(ctx, "trails: best-effort delete of orphaned branch after create-trail failure failed",
			slog.String("repo", repo.FullName()), slog.String("branch", branch), slog.String("detail", del.Detail))
	}
}

