// registerReviews wires the review-family routes onto both addressing schemes
// (ID-001), called from registerTrails (trails.go) alongside registerThreads.
func registerReviews(api huma.API, deps *RepoActivityDeps) {
	readGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsAccess(api, deps)}
	readByIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsAccessByID(api, deps)}
	writeGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccess(api, deps)}
	writeByIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccessByID(api, deps)}
	// publishGate/publishByIDGate admit EITHER an interactive push-holding
	// caller OR a service caller holding the platform publish_review
	// permission (see reviews_authz.go) — used ONLY by start-review and
	// batch-comments, the two routes entire.io's background publish worker
	// (ENT-1254) writes through. Every other review-family write stays on the
	// unchanged writeGate/writeByIDGate above.
	publishGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireReviewPublishAccess(api, deps)}
	publishByIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireReviewPublishAccessByID(api, deps)}

	readOp := func(id, method, path, summary string, gate []opMiddleware) huma.Operation {
		return teamOp(id, method, path, summary, "trails", gate)
	}
	writeOp := func(id, method, path, summary string, gate []opMiddleware) huma.Operation {
		return teamOp(id, method, path, summary, "trails", gate)
	}

	// POST .../reviews — start a review (201, Idempotency-Key).
	startOp := writeOp("reviewStart", http.MethodPost,
		"/trails/{host}/{owner}/{repo}/{number}/reviews", "Start a code review", publishGate)
	startOp.DefaultStatus = http.StatusCreated
	// 409: withIdempotency can return an Idempotency-Key conflict (reviews_idempotency.go).
	startOp.Errors = withExtraErrors(startOp.Errors, http.StatusConflict, http.StatusNotFound)
	huma.Register(api, startOp,
		func(ctx context.Context, in *ReviewStartInput) (*ReviewStartOutput, error) {
			rep, trail, body, err := resolveReviewStart(ctx, deps, in.Number, in.RawBody)
			if err != nil {
				return nil, err
			}
			return withIdempotency(deps, http.StatusCreated,
				func(i *ReviewStartInput) string { return i.IdempotencyKey },
				func(*ReviewStartInput) string { return "reviews:start:" + trail.ID },
				func(ctx context.Context, _ *ReviewStartInput) (*ReviewStartOutput, error) {
					return reviewStartExec(ctx, deps, rep, trail, body, func(reviewID string) reviewStartURLs {
						return reviewStartURLs{
							selfURL:        fmt.Sprintf("%s/trails/%s/%s/%s/%d/reviews/%s", APIBase, in.Host, in.Owner, in.Repo, trail.Number, reviewID),
							eventStreamURL: fmt.Sprintf("%s/trails/%s/%s/%s/%d/events", APIBase, in.Host, in.Owner, in.Repo, trail.Number),
							diffURL:        fmt.Sprintf("%s/trails/%s/%s/%s/%d/reviews/%s/diff", APIBase, in.Host, in.Owner, in.Repo, trail.Number, reviewID),
							filesURL:       fmt.Sprintf("%s/trails/%s/%s/%s/%d/reviews/%s/files", APIBase, in.Host, in.Owner, in.Repo, trail.Number, reviewID),
						}
					})
				})(ctx, in)
