func parseNonNegIntDefault(raw string, def int, field string) (int, error) {
	if strings.TrimSpace(raw) == "" {
		return def, nil
	}
	v, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil || v < 0 {
		return 0, huma.Error400BadRequest(field + " must be a non-negative integer")
	}
	return v, nil
}

func parseNonNegInt64Default(raw string, def int64, field string) (int64, error) {
	if strings.TrimSpace(raw) == "" {
		return def, nil
	}
	v, err := strconv.ParseInt(strings.TrimSpace(raw), 10, 64)
	if err != nil || v < 0 {
		return 0, huma.Error400BadRequest(field + " must be a non-negative integer")
	}
	return v, nil
}

