		func(ctx context.Context, in *ThreadMessageDeleteInput) (*ThreadMessageDeleteOutput, error) {
			return threadMessageDeleteCore(ctx, deps, in.Number, in.ThreadID, in.MessageID)
		})
	msgDeleteByIDOp := writeOp("threadMessageDeleteByRepoID", http.MethodDelete,
		"/repos/{repo_id}/trails/{number}/threads/{threadId}/messages/{messageId}", "Delete a message (repo_id addressing)", writeByIDGate)
	msgDeleteByIDOp.DefaultStatus = http.StatusNoContent
	msgDeleteByIDOp.Errors = withExtraErrors(msgDeleteByIDOp.Errors, http.StatusNotFound)
	huma.Register(api, msgDeleteByIDOp,
		func(ctx context.Context, in *ThreadMessageDeleteByRepoIDInput) (*ThreadMessageDeleteOutput, error) {
			return threadMessageDeleteCore(ctx, deps, in.Number, in.ThreadID, in.MessageID)
