package httpapi

// Trails threads wire types + validation (RFD-023 trails-native port, PR 3).
// Ported from the trails-service spike's src/thread-validation.ts (git show
// spike/trails-stack-8-devex:spikes/trails-service/src/thread-validation.ts)
// — same limits, same error messages, re-cased to camelCase per the ledger
// (T1: trail_id→trailId, resolved_by→resolvedBy, etc.) and paginated per the
// list-read convention (T2: {items, nextPageToken, eventCursor}).
//
// Every optional JSON body field is bound as json.RawMessage, same rationale
// as trailCreateBody/trailUpdateBody (trails_write.go): the spike's
// validation distinguishes "key absent" from "key present" (undefined vs. a
// real value, including null), which a plain Go-typed field can't preserve
// through Huma's schema-based body binding.

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/oklog/ulid/v2"

	"github.com/entirehq/entire-api/internal/store"
)

// TrailThreadMessageBodyMaxLength / TrailThreadTitleMaxLength are
// TRAIL_THREAD_MESSAGE_BODY_MAX_LENGTH / TRAIL_THREAD_TITLE_MAX_LENGTH
// (thread-validation.ts).
const (
	TrailThreadMessageBodyMaxLength = 65_536
	TrailThreadTitleMaxLength       = 512
)

// ---- validators (pure) ----

// parseThreadMessageBody is parseThreadMessageBody (thread-validation.ts):
// absent/null/non-string and empty-after-trim both 400 "Message body is
// required" (the spike's single `typeof raw !== "string"` check already
// covers null and absent identically, so this port folds that presence
// check into the same error rather than a separate "required" message).
//
// Length is counted in runes, not bytes: the spike counts JS `.length`
// (UTF-16 code units), which this port can't reproduce exactly without a
// UTF-16 encoder — rune count is the same documented approximation already
// used by the title-derivation truncation (store.deriveDiscussionThreadTitle),
// so both length-sensitive code paths in this feature treat "characters"
// consistently, even though neither is byte-for-byte identical to the JS
// original for non-BMP input near the boundary.
func parseThreadMessageBody(raw json.RawMessage) (string, *trailValidationError) {
	s, ok := rawAsString(raw)
	if !ok {
		return "", &trailValidationError{http.StatusBadRequest, "Message body is required"}
	}
	body := strings.TrimSpace(s)
	if body == "" {
		return "", &trailValidationError{http.StatusBadRequest, "Message body is required"}
	}
	if utf8.RuneCountInString(body) > TrailThreadMessageBodyMaxLength {
		return "", &trailValidationError{http.StatusBadRequest,
			fmt.Sprintf("Message body must be %d characters or fewer", TrailThreadMessageBodyMaxLength)}
	}
	return body, nil
}

// parseOptionalThreadTitle is parseOptionalThreadTitle (thread-validation.ts):
// absent → (nil, nil); present-but-not-a-string (including JSON null, which
// is present-but-typeof-object in JS terms) → 400 "must be a string";
// empty-after-trim → 400 "is required"; over length → 400; else the trimmed
// title. Length is rune-counted — see parseThreadMessageBody's doc.
func parseOptionalThreadTitle(raw json.RawMessage) (*string, *trailValidationError) {
	if !rawPresent(raw) {
		return nil, nil
	}
	s, ok := rawAsString(raw)
	if !ok {
		return nil, &trailValidationError{http.StatusBadRequest, "Thread title must be a string"}
	}
	title := strings.TrimSpace(s)
	if title == "" {
		return nil, &trailValidationError{http.StatusBadRequest, "Thread title is required"}
	}
	if utf8.RuneCountInString(title) > TrailThreadTitleMaxLength {
		return nil, &trailValidationError{http.StatusBadRequest,
			fmt.Sprintf("Thread title must be %d characters or fewer", TrailThreadTitleMaxLength)}
	}
	return &title, nil
}

// parseOptionalResolved is the PATCH thread route's `resolved` field check
// (app.ts: `if (body.resolved !== undefined && typeof body.resolved !==
// "boolean")`): absent → (nil, nil); present-but-non-bool (including null)
// → 400 "resolved must be a boolean"; else the decoded bool.
func parseOptionalResolved(raw json.RawMessage) (*bool, *trailValidationError) {
	if !rawPresent(raw) {
		return nil, nil
	}
	if string(raw) == "null" {
		return nil, &trailValidationError{http.StatusBadRequest, "resolved must be a boolean"}
	}
	var b bool
	if err := json.Unmarshal(raw, &b); err != nil {
		return nil, &trailValidationError{http.StatusBadRequest, "resolved must be a boolean"}
	}
	return &b, nil
}

// isValidRouteULID replaces the spike's isValidRouteUuid (thread-validation.ts):
// native thread/message ids are ULIDs, not UUIDv7 (ledger T3) — a malformed
// value is treated as "not found" by the caller (collapsed 404), same as the
// spike treats a malformed UUID.
func isValidRouteULID(value string) bool {
	if value == "" {
		return false
	}
	_, err := ulid.Parse(value)
	return err == nil
}

// ---- wire types (camelCase; ledger T1) ----

type threadParticipantJSON struct {
	Login string `json:"login"`
}

type threadMessageReplyJSON struct {
	ID        string `json:"id"`
	Author    string `json:"author"`
	CreatedAt string `json:"createdAt"`
	Body      string `json:"body"`
}

type threadMessageJSON struct {
	ID        string                   `json:"id"`
	Author    string                   `json:"author"`
	CreatedAt string                   `json:"createdAt"`
	Body      string                   `json:"body"`
	Replies   []threadMessageReplyJSON `json:"replies"`
}

// isoMillisPtr is isoMillis (trails_types.go) lifted over *time.Time: nil →
// nil, matching every nullable timestamp field on the threads wire shapes.
func isoMillisPtr(t *time.Time) *string {
	if t == nil {
		return nil
	}
	s := isoMillis(*t)
	return &s
}

// toThreadMessageJSON is messageRecordToMessage (thread-messages.ts) ported
// to the wire shape. Replies always serializes as [] (never null), even for
// a message with none.
func toThreadMessageJSON(m store.ThreadMessage) threadMessageJSON {
	replies := make([]threadMessageReplyJSON, 0, len(m.Replies))
	for _, r := range m.Replies {
		replies = append(replies, threadMessageReplyJSON{
			ID: r.ID, Author: r.Author, CreatedAt: isoMillis(r.CreatedAt), Body: r.Body,
		})
	}
	return threadMessageJSON{ID: m.ID, Author: m.Author, CreatedAt: isoMillis(m.CreatedAt), Body: m.Body, Replies: replies}
}

type threadSummaryJSON struct {
	ID                string                  `json:"id"`
	TrailID           string                  `json:"trailId"`
	Title             string                  `json:"title"`
	Kind              string                  `json:"kind"`
	Resolved          bool                    `json:"resolved"`
	ResolvedBy        *string                 `json:"resolvedBy"`
	ResolvedAt        *string                 `json:"resolvedAt"`
	CreatedBy         *string                 `json:"createdBy"`
	CreatedAt         string                  `json:"createdAt"`
	UpdatedAt         string                  `json:"updatedAt"`
	LastMessageAt     *string                 `json:"lastMessageAt"`
	LastMessageAuthor *string                 `json:"lastMessageAuthor"`
	MessageCount      int                     `json:"messageCount"`
	Participants      []threadParticipantJSON `json:"participants"`
	ReviewCommentID   *string                 `json:"reviewCommentId"`
	// ReviewComment is the §9.5 hydration: non-nil (and populated via
	// toReviewCommentJSON) exactly for a code_review-kind thread, nil for a
	// discussion. Wired live in PR 7 (Task 5) — reviewCommentJSON is defined in
	// reviews_types.go, same package.
	ReviewComment *reviewCommentJSON `json:"reviewComment"`
}

// displayNamePtr resolves an actor ULID against a batch-resolved login map for
// the *string ActorDisplayName field: an empty id, or one absent from the map
// (unresolved login), yields nil (serialized as explicit JSON null); a resolved
// id yields a pointer to its login.
func displayNamePtr(m map[string]string, id string) *string {
	if id == "" {
		return nil
	}
	name, ok := m[id]
	if !ok {
		return nil
	}
	return &name
}

// toThreadSummaryJSON is threadRecordToSummary's (thread-summaries.ts) wire
// projection: nullable account ids/timestamps serialize as explicit null
// ("" / zero-value in the store shape), never omitted. actorDisplayNames is the
// caller-supplied batch-resolved actor-login map for hydrating a code_review
// thread's embedded reviewComment.actorDisplayName (§9.5); a discussion thread
// ignores it.
func toThreadSummaryJSON(s store.ThreadSummary, actorDisplayNames map[string]string) threadSummaryJSON {
	participants := make([]threadParticipantJSON, 0, len(s.Participants))
	for _, p := range s.Participants {
		participants = append(participants, threadParticipantJSON{Login: p.Login})
	}
	var reviewComment *reviewCommentJSON
	if s.ReviewComment != nil {
		j := toReviewCommentJSON(*s.ReviewComment, displayNamePtr(actorDisplayNames, s.ReviewComment.ActorID))
		reviewComment = &j
	}
	return threadSummaryJSON{
		ID: s.ID, TrailID: s.TrailID, Title: s.Title, Kind: s.Kind, Resolved: s.Resolved,
		ResolvedBy: nullableString(s.ResolvedBy), ResolvedAt: isoMillisPtr(s.ResolvedAt),
		CreatedBy: nullableString(s.CreatedBy), CreatedAt: isoMillis(s.CreatedAt), UpdatedAt: isoMillis(s.UpdatedAt),
		LastMessageAt: isoMillisPtr(s.LastMessageAt), LastMessageAuthor: nullableString(s.LastMessageAuthor),
		MessageCount: s.MessageCount, Participants: participants,
		ReviewCommentID: nullableString(s.ReviewCommentID), ReviewComment: reviewComment,
	}
}

// ---- response envelopes ----

// threadsListResponseBody is GET .../threads's body (ledger T2): paginated
// per the list-read convention, `eventCursor` retained as an additional
// field (the polling watermark, exempt from pagination).
type threadsListResponseBody struct {
	Items         []threadSummaryJSON `json:"items"`
	NextPageToken *string             `json:"nextPageToken"`
	EventCursor   string              `json:"eventCursor"`
