type threadDetailResponseBody struct {
	Thread      threadSummaryJSON   `json:"thread"`
	Messages    []threadMessageJSON `json:"messages"`
	EventCursor string              `json:"eventCursor"`
}

// threadCreateResponseBody is POST .../threads's body.
type threadCreateResponseBody struct {
	Thread  threadSummaryJSON  `json:"thread"`
	Message *threadMessageJSON `json:"message"`
}

// threadUpdateResponseBody is PATCH .../threads/{threadId}'s body.
type threadUpdateResponseBody struct {
