// trailNumberPattern mirrors parseTrailNumber (route-context.ts): a positive
// integer with no leading zero, up to 10 digits — the upper bound is enforced
// separately below, not by this pattern (see parseTrailNumber's range check).
var trailNumberPattern = regexp.MustCompile(`^[1-9][0-9]{0,9}$`)

// parseTrailNumber's range cap is Postgres INTEGER's max (2^31-1), NOT the
// route-context.ts spike's INT UNSIGNED max (2^32-1, MySQL parity): this
// cell's repo_trails.number column is a Postgres INTEGER (signed int32), so a
// number in [2^31, 2^32) would pass the spike-parity range, then fail the DB
// bind with a 500 — correctness fix: trail number upper bound wider than the
// column that stores it.
func parseTrailNumber(raw string) (int, bool) {
	if !trailNumberPattern.MatchString(raw) {
		return 0, false
	}
	n, err := strconv.Atoi(raw)
	if err != nil || n < 1 || n > 2_147_483_647 {
		return 0, false
	}
	return n, true
}

// resolveTrailByNumberParam is resolveTrailContext's trail-number half
// (route-context.ts): parse the {number} path param, then look the trail up
// scoped to repoID. Both failure messages are exact spike parity.
func resolveTrailByNumberParam(ctx context.Context, deps *RepoActivityDeps, repoID, raw string) (store.TrailDetailRow, error) {
	n, ok := parseTrailNumber(raw)
	if !ok {
		return store.TrailDetailRow{}, huma.Error400BadRequest("Invalid trail number format")
	}
	row, ok, err := deps.Store.TrailByNumber(ctx, repoID, n)
	if err != nil {
		return store.TrailDetailRow{}, huma.Error500InternalServerError("store: trail by number", err)
	}
	if !ok {
		return store.TrailDetailRow{}, huma.Error404NotFound("Trail not found")
	}
	return row, nil
}

// ---- optimistic concurrency (CONC-001: If-Match / ETag) ----

// trailETag computes a weak ETag from a trail row's updated_at: W/"<RFC3339Nano
// updated_at>". Weak because the wire representation derived from updated_at
// (e.g. the trail's own updatedAt field) is not byte-identical to this token,
// only equivalent — the RFC 9110 rationale for preferring a weak validator.
func trailETag(updatedAt time.Time) string {
	return `W/"` + updatedAt.UTC().Format(time.RFC3339Nano) + `"`
}

// checkTrailIfMatch enforces an OPTIONAL If-Match precondition against row's
// current ETag: an absent header is a no-op (nil, proceed exactly as before
// CONC-001 — existing callers send none and must keep working); a present
// header that doesn't match row's current trailETag is a 412 Precondition
// Failed, returned BEFORE any mutation runs.
func checkTrailIfMatch(ifMatch string, row store.TrailDetailRow) error {
	if strings.TrimSpace(ifMatch) == "" {
		return nil
	}
	if strings.TrimSpace(ifMatch) != trailETag(row.UpdatedAt) {
		return huma.Error412PreconditionFailed("If-Match does not match the trail's current ETag")
	}
	return nil
}

// trailIfMatchPrecondition parses a validated If-Match header (one that has
// already passed checkTrailIfMatch, so its shape is guaranteed well-formed)
// into the store-level CONC-001 precondition: nil when no If-Match was
// supplied (apply unconditionally, unchanged pre-CONC-001 behavior), else the
// updated_at instant it encodes — threaded into UpdateTrailMetadata/
// DeleteTrail so the precondition is re-checked atomically under the row's
// FOR UPDATE lock, closing the check-then-act race checkTrailIfMatch's cheap
// early check alone cannot prevent (see store.ErrPreconditionFailed).
func trailIfMatchPrecondition(ifMatch string) *time.Time {
	trimmed := strings.TrimSpace(ifMatch)
	if trimmed == "" {
		return nil
	}
	t, ok := parseTrailETag(trimmed)
	if !ok {
		// Unreachable in practice: checkTrailIfMatch already string-compared
		// ifMatch against trailETag(row.UpdatedAt), which is always
		// well-formed — but degrade to "no precondition" rather than panic if
		// this is ever reached some other way.
		return nil
	}
	return &t
}

// parseTrailETag parses a weak ETag of trailETag's exact shape
// (W/"<RFC3339Nano>"), returning the encoded instant.
func parseTrailETag(etag string) (time.Time, bool) {
	if !strings.HasPrefix(etag, `W/"`) || !strings.HasSuffix(etag, `"`) {
		return time.Time{}, false
	}
	inner := etag[len(`W/"`) : len(etag)-1]
	t, err := time.Parse(time.RFC3339Nano, inner)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

