// the request context — a client disconnect (ctx cancelled) ends it silently.
func sseConnection(ctx context.Context, s *sseWriter, hub *trailHub, authorized func(context.Context) (bool, error), ready sseReadyData, startAfter int64, eventTypes []string, presence TrailWatchPresence, conn TrailWatchConn) {
	// Clamp a client-supplied future cursor to the log's current head, so a cursor
	// ahead of the log can never skip past events that land after it. The read is
	// load-bearing (an unclamped future cursor would leave the stream permanently
	// empty on `id > cursor`), so a read failure ends the connection with an error
	// frame rather than proceeding — the client reconnects and retries, matching the
	// DO's fail-closed stream-init behaviour.
	head, err := hub.src.head(ctx)
	if err != nil {
		if ctx.Err() == nil {
			slog.WarnContext(ctx, "trails: events SSE cursor clamp read failed",
				slog.String("repo_id", conn.RepoID), slog.String("trail_id", ready.TrailID), slog.Any("error", err))
			s.frame("error", "", sseError())
		}
		return
	}
	cursor := startAfter
	if cursor > head {
		cursor = head
	}
	ready.Cursor = cursor
	if !s.frame("ready", "", ready) {
		return
	}

	if presence != nil {
		conn.ConnectionID = newSSEConnectionID()
		presence.Open(ctx, conn)
		// Close with a live context: the client disconnect that ends the loop has
		// already cancelled ctx, but a presence DELETE must still run.
		defer presence.Close(context.WithoutCancel(ctx), conn)
	}

	hc := hub.add(eventTypes, cursor, head)

