}

// newSSEConnectionID returns a random per-connection id for the presence key. A
// crypto/rand failure (never observed in practice) degrades to an empty id rather
// than failing the stream — presence is best-effort decoration.
func newSSEConnectionID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return ""
	}
	return hex.EncodeToString(b[:])
}

