package httpapi

// Wholesale content-replace for an editor document (ENT-1486 slice 3): the
// non-Yjs write path for a caller that has a whole document — automation,
// CLI, MCP — rather than a Yjs update to merge. Layered on the same
// yjsengine.Client the merge route (editor_updates.go) uses, via SetContent
// instead of Merge, and on the same guarded MergeEditorDocument write — see
// that file's header for why a version-guarded UPDATE, not a lock, is the
// concurrency primitive here.
//
// Unlike a Yjs merge, a wholesale replace has no way to reconcile with a
// concurrent write — it must either refuse to clobber one or be told not to
// care. Two independent, orthogonal controls cover that:
//
//   - concurrency: the CONC-001 If-Match header (trails_write.go), a weak
//     ETag over updated_at. Mismatch is 412; omitted applies unconditionally.
//   - "is there anything to lose?": the onlyIfEmpty body flag, which is NOT
//     concurrency control and fails differently — a 200 no-op carrying
//     isApplied=false, not a 412.
//
// They compose: a caller wanting both sends both.

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"strings"
	"time"

	"github.com/danielgtaylor/huma/v2"
	"github.com/oklog/ulid/v2"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	"github.com/entirehq/entire-api/internal/httpapi/editorjson"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entirehq/entire-api/internal/yjsengine"
)

// reasonDocumentNotEmpty is the editorContentPutResponseJSON.Reason value for
// an onlyIfEmpty write that no-op'd because the document already has content.
const reasonDocumentNotEmpty = "document_not_empty"

// ---- optimistic concurrency (CONC-001: If-Match / ETag) ----

// editorDocumentETag computes a weak ETag from an editor document's
// updated_at, mirroring trailETag's (trails_write.go) shape and rationale:
// weak because the wire representation derived from updated_at is equivalent
// but not byte-identical to this token.
//
// Note the precision. The token is RFC3339Nano — the full instant Postgres
// stores — while the body's updatedAt field is millisecond-truncated for the
// wire (isoMillis). Comparing ETags therefore compares exactly what the
// store's ExpectedUpdatedAt guard compares, which is the whole point: a
// truncated comparison would admit a same-millisecond write the guard rejects.
func editorDocumentETag(updatedAt time.Time) string {
	return `W/"` + updatedAt.UTC().Format(time.RFC3339Nano) + `"`
}

type editorContentPutBody struct {
	ContentJSON        json.RawMessage `json:"contentJson" doc:"Replacement editor-document content (ProseMirror JSON). Required."`
	UpdatedByAccountID string          `json:"updatedByAccountId,omitempty" doc:"Account (ULID) the write is attributed to. Exactly one of updatedByAccountId/updatedByActorRef is required."`
	UpdatedByActorRef  string          `json:"updatedByActorRef,omitempty" doc:"Non-account actor (e.g. an automation principal) the write is attributed to. Exactly one of updatedByAccountId/updatedByActorRef is required."`
	SchemaVersion      int             `json:"schemaVersion,omitempty" doc:"Editor schema version; only 1 is supported."`
	OnlyIfEmpty        bool            `json:"onlyIfEmpty,omitempty" doc:"Apply only while the document is structurally empty: every node is the top doc node or a paragraph (any number of blank paragraphs, or an empty content array, still counts as empty), and no text node holds non-whitespace text. Any other node type — horizontalRule, taskList/taskItem, codeBlock, blockquote, attachmentImage, heading, bulletList/orderedList, hardBreak, … — counts as content even when it renders no visible text of its own. A document that already has content is a 200 no-op, not an error: see the response's isApplied/reason. This is not concurrency control — combine it with If-Match if you need both."`
}

// EditorContentPutInput carries the CONC-001 If-Match header alongside the
// body. Concurrency control is the header's job, not the body's: onlyIfEmpty
// is a separate, orthogonal question ("is there anything to lose?") that fails
// differently — a 200 no-op rather than a 412.
type EditorContentPutInput struct {
	DocumentKey string `path:"documentKey" doc:"Editor document key."`
	IfMatch     string `header:"If-Match" doc:"Optimistic concurrency: a weak ETag (W/\"<updatedAt>\") from a prior read/write of this document, as returned by the sync GET or this route. If present, the request 412s when it no longer matches the document's current ETag. Omit to apply unconditionally."`
	Body        editorContentPutBody
}

// editorContentPutResponseJSON embeds EditorSyncDocumentJSON so a caller gets
// the same document shape the sync/merge routes return, plus whether this
// write actually applied. IsApplied=false only for the onlyIfEmpty no-op: the
// document is returned as-is (not the caller's rejected content) so the
// response is never mistaken for a write that happened.
type editorContentPutResponseJSON struct {
	IsApplied bool   `json:"isApplied" doc:"Whether this write replaced the document's content."`
	Reason    string `json:"reason,omitempty" doc:"Set when isApplied is false; currently: document_not_empty."`
	EditorSyncDocumentJSON
}

// registerEditorContent wires the content-replace route behind the same gate
// as registerEditorUpdates: the platform sync-editor-documents permission.
func registerEditorContent(api huma.API, deps *RepoActivityDeps) {
	gate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireEditorSyncAccess(api, deps)}

	op := teamOp("editorContentPut", http.MethodPut,
		"/editor-documents/{documentKey}/content",
		"Replace an editor document's content wholesale (service)", "trails", gate)
	op.Errors = withExtraErrors(op.Errors,
		http.StatusUnauthorized, http.StatusForbidden, http.StatusNotFound,
		http.StatusServiceUnavailable, http.StatusUnprocessableEntity,
		http.StatusPreconditionFailed,
		// The mux-wide front-door throttle (router.go) can reject any route
		// before it ever reaches this handler, same as the sibling merge route.
		http.StatusTooManyRequests)
	huma.Register(api, op,
		func(ctx context.Context, in *EditorContentPutInput) (*EditorContentPutOutput, error) {
			return editorContentPut(ctx, deps, in)
		})
}

// EditorContentPutOutput carries the resulting document's weak ETag
// (CONC-001) for a later If-Match write, matching the gate-definition write
// routes. On an onlyIfEmpty no-op it is the ETag of the document as it stands
// — the value a caller needs to retry against what is actually there.
type EditorContentPutOutput struct {
	ETag string `header:"ETag"`
	Body editorContentPutResponseJSON
}

func editorContentPut(ctx context.Context, deps *RepoActivityDeps, in *EditorContentPutInput) (*EditorContentPutOutput, error) {
	if len(in.Body.ContentJSON) == 0 {
		return nil, huma.Error422UnprocessableEntity("contentJson is required")
	}
	hasAccount := in.Body.UpdatedByAccountID != ""
	hasActorRef := in.Body.UpdatedByActorRef != ""
	if hasAccount == hasActorRef {
		return nil, huma.Error422UnprocessableEntity("exactly one of updatedByAccountId/updatedByActorRef is required")
	}
	if hasAccount {
		if _, err := ulid.Parse(in.Body.UpdatedByAccountID); err != nil {
			return nil, huma.Error422UnprocessableEntity("updatedByAccountId must be a ULID")
		}
	} else if !store.ValidActorRef(in.Body.UpdatedByActorRef) {
		return nil, huma.Error422UnprocessableEntity("updatedByActorRef is not a recognized actor ref")
	}

	ifMatch := strings.TrimSpace(in.IfMatch)

	if in.Body.SchemaVersion != 0 && in.Body.SchemaVersion != editorjson.SchemaVersion {
		return nil, huma.Error422UnprocessableEntity("unsupported schemaVersion")
	}
	schemaVersion := in.Body.SchemaVersion
	if schemaVersion == 0 {
		schemaVersion = editorjson.SchemaVersion
	}
	if deps.YjsEngine == nil {
		return nil, huma.Error503ServiceUnavailable("yjs engine is not configured")
