			}
			if !ok {
				return nil, huma.Error404NotFound("Editor document not found")
			}
		}

		// Both checks re-run every attempt against doc as just (re-)read: the
		// If-Match check so a write-time conflict resolves to the same 412 as a
		// check-time mismatch, and onlyIfEmpty so emptiness is re-evaluated
		// against whatever a competing writer left behind.
		if ifMatch != "" && ifMatch != editorDocumentETag(doc.UpdatedAt) {
			return nil, huma.Error412PreconditionFailed("If-Match does not match the document's current ETag")
