					Reason:                 reasonDocumentNotEmpty,
					EditorSyncDocumentJSON: toEditorSyncDocumentJSON(doc),
				},
			}, nil
		}

		result, err := deps.YjsEngine.SetContent(ctx, doc.YjsState, in.Body.ContentJSON)
		if err != nil {
			if errors.Is(err, yjsengine.ErrBadRequest) {
				return nil, huma.Error422UnprocessableEntity("the editor engine rejected this content", err)
			}
			slog.ErrorContext(ctx, "yjs setContent: sidecar failure",
				slog.String("document_key", key), slog.Any("error", err))
