		}

		res, err := deps.Store.MergeEditorDocument(ctx, store.MergeEditorDocumentInput{
			DocumentKey:        key,
			DocumentID:         doc.ID,
			YjsState:           result.State,
			ContentJSON:        result.ContentJSON,
			UpdatedByAccountID: in.Body.UpdatedByAccountID,
			UpdatedByActorRef:  nullableString(in.Body.UpdatedByActorRef),
			SchemaVersion:      schemaVersion,
			ExpectYjsUpdatedAt: doc.YjsUpdatedAt,
			// Always set, independent of If-Match: this is the route's own
			// read-modify-write guard ("the row I read is the row I am
			// writing"), which is what makes the retry loop correct. If-Match
			// is the caller's separate assertion about what THEY read.
			ExpectedUpdatedAt: &doc.UpdatedAt,
