// requirePlatformPermission (authz.go), which owns the shared fail-closed
// ladder.
func requireEditorSyncAccess(api huma.API, deps *RepoActivityDeps) opMiddleware {
	return requirePlatformPermission(api, deps, authz.SyncEditorDocuments, "editor sync requires sync-editor-documents authorization")
}

